    // ---------------------------------------------------------------------------

    /**
     * @param bars [{ x, w, y, color?, label?, value? }]，x 为柱心，y 为高度（基线 0）
     */
    function drawBars(ctx, view, pal, bars, opts) {
      const o = opts || {};
      const base = o.base === undefined ? 0 : o.base;
      const baseY = view.toY(base);
      bars.forEach((bar) => {
        const left = view.toX(bar.x - bar.w / 2);
        const right = view.toX(bar.x + bar.w / 2);
        const top = view.toY(bar.y);
        ctx.save();
        ctx.fillStyle = bar.color || o.color || pal.accent;
        if (o.alpha !== undefined) ctx.globalAlpha = o.alpha;
        ctx.fillRect(left, Math.min(top, baseY), Math.max(1, right - left), Math.abs(baseY - top));
        ctx.globalAlpha = 1;
        if (bar.label) tag(ctx, bar.label, (left + right) / 2, baseY + 12, pal.muted, 'center', 10);
        if (bar.value) tag(ctx, bar.value, (left + right) / 2, top - 9, pal.text, 'center', 10);
        ctx.restore();
      });
    }

    /** 角度读数：0.5236 → 30° */
    function degText(rad, digits) {
      return `${fnum((rad * 180) / PI, digits === undefined ? 1 : digits)}°`;
    }

    /** 数值导数（非解析函数用），h 自适应步长 */
    function numericDiff(f, x) {
      const h = 1e-5 * Math.max(1, Math.abs(x));
      return (f(x + h) - f(x - h)) / (2 * h);
    }

    /** 把无限直线裁剪到画布可见范围，返回 [[x1,y1],[x2,y2]] 或 null */
    function clipLineToView(view, x0, y0, dx, dy) {
      const len = Math.hypot(dx, dy);
      if (len < 1e-12) return null;
      const ux = dx / len;
      const uy = dy / len;
      const ts = [];
      if (Math.abs(ux) > 1e-12) {
        ts.push((view.x0 - x0) / ux, (view.x1 - x0) / ux);
      }
      if (Math.abs(uy) > 1e-12) {
        ts.push((view.y0 - y0) / uy, (view.y1 - y0) / uy);
      }
      const hits = [];
      ts.forEach((t) => {
        const x = x0 + ux * t;
        const y = y0 + uy * t;
        if (x >= view.x0 - 1e-6 && x <= view.x1 + 1e-6 && y >= view.y0 - 1e-6 && y <= view.y1 + 1e-6) hits.push([x, y]);
      });
      if (hits.length < 2) return null;
      return [hits[0], hits[hits.length - 1]];
    }

    /** 过点 (x0,y0)、方向 (dx,dy) 的无限直线（自动裁到视口） */
    function lineThroughWorld(ctx, view, x0, y0, dx, dy, color, width, pattern) {
      const seg = clipLineToView(view, x0, y0, dx, dy);
      if (!seg) return;
      segmentWorld(ctx, view, seg[0][0], seg[0][1], seg[1][0], seg[1][1], color, width, pattern);
    }

    /** 最大公约数 */
    function gcd(a, b) {
      let x = Math.abs(Math.round(a));
      let y = Math.abs(Math.round(b));
      while (y) {
        const t = x % y;
        x = y;
        y = t;
      }
      return x || 1;
    }

    /** 约分后的分数文本：3/8、1/2、2 */
    function fracText(num, den) {
      if (!Number.isFinite(num) || !Number.isFinite(den) || den === 0) return '—';
      const g = gcd(num, den);
      const n = Math.round(num / g);
      const d = Math.round(den / g);
      if (d === 1) return String(n);
      return `${n}/${d}`;
    }

    /** 组合数文本 C(n,k) */
    function combText(n, k) {
      return `C(${n},${k})`;
    }

    /** 世界坐标下的箭头（原点 + 分量） */
    function vectorWorld(ctx, view, ox, oy, vx, vy, color, label, width) {
      arrowWorld(ctx, view, ox, oy, ox + vx, oy + vy, color, width === undefined ? 2.2 : width);
      if (label) {
        labelWorld(ctx, view, label, ox + vx * 0.55 + (view.x1 - view.x0) * 0.03, oy + vy * 0.55 + (view.y1 - view.y0) * 0.04, color, 'left', 11);
      }
    }

    // ---------------------------------------------------------------------------
    // 极简 3D：正交投影 + 绕 Y 偏航 / 绕 X 俯仰（立体几何用，零依赖）
    // ---------------------------------------------------------------------------

    const camera3D = { yaw: -0.62, pitch: 0.34, touched: false };

    function makeCamera3D(width, height, span, center, pitchOverride) {
      const cosY = Math.cos(camera3D.yaw);
      const sinY = Math.sin(camera3D.yaw);
      const pitch = camera3D.touched || pitchOverride === undefined ? camera3D.pitch : pitchOverride;
      const cosP = Math.cos(pitch);
      const sinP = Math.sin(pitch);
      const scale = Math.min(width, height) / Math.max(span, 1e-6);
      const cx = width / 2;
      const cy = height * 0.54;
      const ox = center ? center[0] : 0;
      const oy = center ? center[1] : 0;
      const oz = center ? center[2] : 0;
      return {
        scale,
        project(x, y, z) {
          const x0 = x - ox;
          const y0 = y - oy;
          const z0 = z - oz;
          const x1 = x0 * cosY + z0 * sinY;
          const z1 = -x0 * sinY + z0 * cosY;
          const y1 = y0 * cosP - z1 * sinP;
          const z2 = y0 * sinP + z1 * cosP;
          return { x: cx + x1 * scale, y: cy - y1 * scale, z: z2 };
        },
      };
    }

    function arrow3D(ctx, cam, from, to, color, width) {
      const a = cam.project(from[0], from[1], from[2]);
      const b = cam.project(to[0], to[1], to[2]);
      arrow(ctx, a.x, a.y, b.x, b.y, color, width);
      return (a.z + b.z) / 2;
    }

    function line3D(ctx, cam, pts, color, width, dashPattern) {
      if (!pts || pts.length < 2) return 0;
      let depth = 0;
      ctx.save();
      if (dashPattern) ctx.setLineDash(dashPattern);
      ctx.strokeStyle = color;
      ctx.lineWidth = width === undefined ? 2 : width;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.beginPath();
      pts.forEach((pt, index) => {
        const q = cam.project(pt[0], pt[1], pt[2]);
        depth += q.z;
        if (index === 0) ctx.moveTo(q.x, q.y);
        else ctx.lineTo(q.x, q.y);
      });
      ctx.stroke();
      ctx.restore();
      return depth / pts.length;
    }

    function tag3D(ctx, cam, text, pt, color, align, size) {
      const q = cam.project(pt[0], pt[1], pt[2]);
      tag(ctx, text, q.x, q.y, color, align || 'center', size || 10);
    }

    function grid3D(ctx, cam, y, x0, x1, z0, z1, pal, step) {
      const gap = step || 0.5;
      ctx.save();
      ctx.strokeStyle = pal.grid;
      ctx.lineWidth = 1;
      for (let x = x0; x <= x1 + 1e-6; x += gap) {
        const a = cam.project(x, y, z0);
        const b = cam.project(x, y, z1);
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
      }
      for (let z = z0; z <= z1 + 1e-6; z += gap) {
        const a = cam.project(x0, y, z);
        const b = cam.project(x1, y, z);
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
      }
      ctx.restore();
    }

    // ---------------------------------------------------------------------------
    // 数值工具：二分求根、梯形积分、连乘
    // ---------------------------------------------------------------------------

    function bisect(f, a, b, iterations) {
      let lo = a;
      let hi = b;
      let flo = f(lo);
      const fhi = f(hi);
      if (!isFinite(flo) || !isFinite(fhi) || flo * fhi > 0) return null;
      const n = iterations || 80;
      for (let i = 0; i < n; i += 1) {
        const mid = (lo + hi) / 2;
        const fmid = f(mid);
        if (!isFinite(fmid)) return mid;
        if (flo * fmid <= 0) {
          hi = mid;
        } else {
          lo = mid;
          flo = fmid;
        }
      }
      return (lo + hi) / 2;
    }

    function integrate(f, a, b, n) {
      const steps = Math.max(2, n || 200);
      const h = (b - a) / steps;
      let sum = 0;
      for (let i = 0; i < steps; i += 1) {
        const x0 = a + i * h;
        const x1 = x0 + h;
        const f0 = f(x0);
        const f1 = f(x1);
        if (isFinite(f0) && isFinite(f1)) sum += ((f0 + f1) / 2) * h;
      }
      return sum;
    }

    function factorial(n) {
      let out = 1;
      for (let i = 2; i <= n; i += 1) out *= i;
      return out;
    }

    function binom(n, k) {
      if (k < 0 || k > n) return 0;
      let out = 1;
      for (let i = 1; i <= k; i += 1) out = (out * (n - k + i)) / i;
      return Math.round(out);
    }

    // ---------------------------------------------------------------------------
    // 答案解析：支持 3/4、√3/2、2π/3、1.2e-3 这类写法
    // ---------------------------------------------------------------------------

    /** 安全表达式求值（不用 eval，避免 CSP 与注入问题） */
    function evalMathExpr(text) {
      let i = 0;
      const src = text;
      const peek = () => src[i];
      const skip = () => {
        while (i < src.length && /\s/.test(src[i])) i += 1;
      };
      function parseExpr() {
        let value = parseTerm();
        for (;;) {
          skip();
          const ch = peek();
          if (ch === '+' || ch === '-') {
            i += 1;
            const rhs = parseTerm();
            value = ch === '+' ? value + rhs : value - rhs;
          } else break;
        }
        return value;
      }
      function parseTerm() {
        let value = parseUnary();
        for (;;) {
          skip();
          const ch = peek();
          if (ch === '*' || ch === '×' || ch === '·' || ch === '/') {
            i += 1;
            const rhs = parseUnary();
            value = ch === '/' ? value / rhs : value * rhs;
          } else if (ch === '(' || /[a-zA-Zπ]/.test(ch || '')) {
            // 隐式乘法：2π、3(4)、2√3
            const rhs = parseUnary();
            value *= rhs;
          } else break;
        }
        return value;
      }
      function parseUnary() {
        skip();
        const ch = peek();
        if (ch === '-') {
          i += 1;
          return -parseUnary();
        }
        if (ch === '+') {
          i += 1;
          return parseUnary();
        }
        return parsePower();
      }
      function parsePower() {
        const base = parseAtom();
        skip();
        if (peek() === '^') {
          i += 1;
          const exp = parseUnary();
          return Math.pow(base, exp);
        }
        return base;
      }
      function parseAtom() {
        skip();
        const ch = peek();
        if (ch === '(') {
          i += 1;
          const value = parseExpr();
          skip();
          if (peek() === ')') i += 1;
          return value;
        }
        if (ch === '√') {
          i += 1;
          return Math.sqrt(Math.abs(parseUnary()));
        }
        if (ch === 'π') {
          i += 1;
          return PI;
        }
        if (ch === 'e' || ch === 'E') {
          i += 1;
          return Math.E;
        }
        const start = i;
        if (ch === '.' || /[0-9]/.test(ch || '')) {
          i += 1;
          while (i < src.length && /[0-9.]/.test(src[i])) i += 1;
          if (src[i] === 'e' || src[i] === 'E') {
            const save = i;
            i += 1;
            if (src[i] === '+' || src[i] === '-') i += 1;
            if (/[0-9]/.test(src[i] || '')) {
              while (i < src.length && /[0-9]/.test(src[i])) i += 1;
            } else {
              i = save;
            }
          }
          return Number(src.slice(start, i));
        }
        // 无法识别的字符：整段失败
        i = src.length;
        return NaN;
      }
      const value = parseExpr();
      skip();
      if (i < src.length) return NaN;
      return value;
    }

    function parseAnswer(input) {
      if (typeof input === 'number') return input;
      let text = String(input === undefined || input === null ? '' : input).trim();
      if (!text) return NaN;
      text = text
        .replace(/[，,]/g, '.')
        .replace(/[−–—－]/g, '-')
        .replace(/[×✕xX]/g, (m) => (m === '×' || m === '✕' ? '*' : m))
        .replace(/π/g, 'π')
        .replace(/√/g, '√')
        .replace(/%/g, '');
      let value = evalMathExpr(text);
      if (!isFinite(value)) {
        const match = text.replace(/,/g, '.').match(/[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?/);
        value = match ? Number(match[0]) : NaN;
      }
      return value;
    }

    /**
     * 判定：相对容差 + 绝对兜底。
     * 兜底不能一律 0.02 —— 概率题答案 0.05 时会把 0.03 也判对；
     * 答案 < 1 的用 1e-3 兜底，答案 ≥ 1 的（整数/根式结果）保留 0.02，容忍四舍五入。
     */
    function toleranceOf(answer, rel) {
      const magnitude = Math.abs(answer);
      const floor = magnitude >= 1 ? 0.02 : 1e-3;
      return Math.max(magnitude * (rel === undefined ? 0.02 : rel), floor);
    }

    function judge(quiz, input) {
      if (!quiz) return false;
      const value = parseAnswer(input);
      if (!isFinite(value)) return false;
      if (Array.isArray(quiz.answers)) {
        return quiz.answers.some((ans) => Math.abs(value - ans) <= toleranceOf(ans, quiz.tol));
      }
      return Math.abs(value - quiz.answer) <= toleranceOf(quiz.answer, quiz.tol);
    }

    // ---------------------------------------------------------------------------
    // 注册表：模型 / 讲解 / 出题 / 例题
    // ---------------------------------------------------------------------------

    const MODELS = [];
    const GRADE_ORDER = [1, 2, 3];

    /**
     * 标签栏里的备课顺序。build.mjs 按文件名拼装，注册顺序是字母序，
     * 这里把每个年级内部恢复成“教材推进/由浅入深”的顺序。
     */
    const MODEL_ORDER = [
      'quadratic', 'graphTransform', 'expLog', 'trigGraph', 'trigIdentity', 'vector', 'triangle', 'inequality',
      'lineCircle', 'ellipse', 'hyperbola', 'parabola', 'derivative', 'monotonic', 'integral', 'series',
      'binomial', 'probability', 'normal', 'linearProgramming', 'complex', 'solid3D', 'zeros', 'regression',
    ];
    const LESSONS = {};
    const QUIZZES = {};
    const EXAM_BANK = [];

    function defineModel(model) {
      MODELS.push(model);
      return model;
    }

    function defineLesson(id, lesson) {
      LESSONS[id] = lesson;
    }

    function defineQuiz(id, generator) {
      QUIZZES[id] = generator;
    }

    function defineExams(list) {
      list.forEach((item) => EXAM_BANK.push(item));
    }

    /** 出题结果的标准结构 */
    function makeQuiz(params, question, unit, answer, solution, tol) {
      return { params, question, unit, answer, solution, tol: tol === undefined ? 0.02 : tol };
    }

    function rpick(rng, list) {
      const i = Math.floor(rng() * list.length);
      return list[Math.min(list.length - 1, Math.max(0, i))];
    }

    function rnum(rng, min, max, step) {
      const n = Math.round((max - min) / step);
      const i = Math.min(n, Math.max(0, Math.floor(rng() * (n + 1))));
      return Number((min + i * step).toFixed(4));
    }

    const modelById = (id) => MODELS.find((m) => m.id === id) || MODELS[0];

    function initialParams(model) {
      const out = {};
      model.params.forEach((p) => {
        out[p.key] = p.init;
      });
      return out;
    }

    /** 该模型的上次参数（缺失或非法就用默认值补齐） */
    function paramsFor(id, store) {
      const model = modelById(id);
      const base = initialParams(model);
      const saved = store && store.params && store.params[id];
      if (!saved) return base;
      Object.keys(base).forEach((key) => {
        const value = saved[key];
        if (value === undefined || value === null) return;
        if (typeof base[key] === 'number' && !Number.isFinite(Number(value))) return;
        base[key] = typeof base[key] === 'number' ? Number(value) : value;
      });
      return base;
    }

    function examsFor(modelId) {
      return EXAM_BANK.filter((item) => item.modelId === modelId);
    }

    /** 取一道样例题：cursor 是每模型自增的序号 */
    function pickExam(modelId, cursor) {
      const list = examsFor(modelId);
      if (!list.length) return null;
      const item = list[((cursor % list.length) + list.length) % list.length];
      return {
        params: item.params,
        question: item.stem,
        unit: item.unit,
        answer: item.answer,
        answers: item.answers,
        solution: item.solution,
        tol: item.tol === undefined ? 0.02 : item.tol,
        source: item.source,
        tag: item.tag,
      };
    }

    function pickQuiz(modelId, rng) {
      const gen = QUIZZES[modelId];
      if (typeof gen !== 'function') return null;
      const random = rng || Math.random;
      for (let i = 0; i < 16; i += 1) {
        const quiz = gen(random);
        if (quiz) return quiz;
      }
      return null;
    }

    // ---------------------------------------------------------------------------
    // 主图之外的副图：按时间轴采样某个量，画成折线
    // ---------------------------------------------------------------------------

    function seriesOf(model, params) {
      const total = Math.max(0.2, model.duration(params));
      const steps = 160;
      const pts = [];
      for (let i = 0; i <= steps; i += 1) {
        const t = (total * i) / steps;
        let value = 0;
        try {
          const st = model.state(t, params);
          value = typeof st.chartValue === 'number' ? st.chartValue : 0;
        } catch (_error) {
          value = 0;
        }
        pts.push({ t, v: isFinite(value) ? value : 0 });
      }
      return { total, pts };
    }

    function drawChart(ctx, width, height, series, pal, markerT, axisLabel) {
      ctx.clearRect(0, 0, width, height);
      const padL = 44;
      const padR = 12;
      const padT = 14;
      const padB = 22;
      const plotW = Math.max(10, width - padL - padR);
      const plotH = Math.max(10, height - padT - padB);

      let rawMax = 0;
      let rawMin = 0;
      series.pts.forEach((p) => {
        rawMax = Math.max(rawMax, p.v);
        rawMin = Math.min(rawMin, p.v);
      });
      let vMax;
      let vMin;
      if (rawMin >= 0) {
        vMin = 0;
        vMax = rawMax > 1e-6 ? rawMax * 1.15 : 1;
      } else if (rawMax <= 0) {
        vMax = 0;
        vMin = rawMin * 1.15;
      } else {
        const gap = (rawMax - rawMin) * 0.12;
        vMax = rawMax + gap;
        vMin = rawMin - gap;
      }

      const toX = (t) => padL + (plotW * t) / series.total;
      const toY = (v) => padT + plotH * (1 - (v - vMin) / (vMax - vMin));

      ctx.save();
      ctx.strokeStyle = pal.grid;
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i += 1) {
        const y = padT + (plotH * i) / 4;
        ctx.beginPath();
        ctx.moveTo(padL, y);
        ctx.lineTo(padL + plotW, y);
        ctx.stroke();
      }
      for (let i = 0; i <= 4; i += 1) {
        const x = padL + (plotW * i) / 4;
        ctx.beginPath();
        ctx.moveTo(x, padT);
        ctx.lineTo(x, padT + plotH);
        ctx.stroke();
      }
      ctx.strokeStyle = pal.axis;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(padL, padT);
      ctx.lineTo(padL, padT + plotH);
      ctx.moveTo(padL, toY(0));
      ctx.lineTo(padL + plotW, toY(0));
      ctx.stroke();
      ctx.restore();

      ctx.save();
      ctx.font = `500 10px ${FONT_UI}`;
      ctx.fillStyle = pal.muted;
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      ctx.fillText(fnum(vMax, 2), padL - 6, padT + 4);
      if (vMin < -1e-6 && vMax > 1e-6) ctx.fillText('0', padL - 6, toY(0));
      ctx.fillText(fnum(vMin, 2), padL - 6, padT + plotH - 4);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillText('0', padL, padT + plotH + 5);
      ctx.fillText(`${fnum(series.total, 1)}`, padL + plotW, padT + plotH + 5);
      ctx.fillText('t', padL + plotW + 7, padT + plotH + 5);
      ctx.textAlign = 'left';
      ctx.fillText(axisLabel || '', padL + 2, padT - 12 > 0 ? padT - 12 : 0);
      ctx.restore();

      ctx.save();
      ctx.strokeStyle = pal.curve2;
      ctx.lineWidth = 2;
      ctx.lineJoin = 'round';
      ctx.beginPath();
      series.pts.forEach((p, i) => {
        const x = toX(p.t);
        const y = toY(p.v);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
      ctx.restore();

      const mx = toX(Math.min(markerT, series.total));
      ctx.save();
      ctx.strokeStyle = pal.dark ? 'rgba(255,255,255,0.35)' : 'rgba(15,23,42,0.28)';
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 4]);
      ctx.beginPath();
      ctx.moveTo(mx, padT);
      ctx.lineTo(mx, padT + plotH);
      ctx.stroke();
      ctx.restore();

      const current = series.pts.reduce((best, p) => (Math.abs(p.t - markerT) < Math.abs(best.t - markerT) ? p : best), series.pts[0]);
      ctx.save();
      ctx.fillStyle = pal.curve2;
      ctx.beginPath();
      ctx.arc(toX(current.t), toY(current.v), 3.6, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // ==========================================================================
    // 模型（24 个文件）
    // ==========================================================================

    // ---- src/models/binomial.js -------------------------------------
    // ---------------------------------------------------------------------------
    // 模型 · 排列组合与二项式定理（高三）
    // ---------------------------------------------------------------------------

    /** 上标数字：7 → ⁷，10 → ¹⁰ */
    function binomialSup(value) {
      const map = '⁰¹²³⁴⁵⁶⁷⁸⁹';
      return String(value)
        .split('')
        .map((ch) => map[Number(ch)] || ch)
        .join('');
    }

    /** 杨辉三角第 n 行：C(n,0) … C(n,n) */
    function binomialRow(n) {
      const row = [];
      for (let k = 0; k <= n; k += 1) row.push(binom(n, k));
      return row;
    }

    /** 排列数 A(n,k) = n(n−1)…(n−k+1) */
    function binomialPerm(n, k) {
      let out = 1;
      for (let i = 0; i < k; i += 1) out *= n - i;
      return out;
    }

    /** (x+1)ⁿ 里含 xᵏ 的项：C(n,k)xᵏ（系数为 1 时省略） */
    function binomialTermText(n, k) {
      const c = binom(n, k);
      if (k === 0) return String(c);
      const coef = c === 1 ? '' : String(c);
      return `${coef}x${k === 1 ? '' : binomialSup(k)}`;
    }

    defineModel({
      id: 'binomial',
      grade: 3,
      name: { zh: '排列组合与二项式定理', en: 'Binomial theorem & Pascal’s triangle' },
      formula: {
        zh: '(x + 1)ⁿ = Σ C(n,k)·xᵏ　·　C(n,k) = n!/(k!(n−k)!)　·　A(n,k) = n!/(n−k)!',
        en: '(x+1)ⁿ = Σ C(n,k)·xᵏ · C(n,k) = n!/(k!(n−k)!) · A(n,k) = n!/(n−k)!',
      },
      hint: {
        zh: '杨辉三角第 n 行就是 (x+1)ⁿ 的二项式系数：C(n,k) 表示从 n 个里选 k 个。每个数等于肩上的两数之和，整行关于中间对称、总和是 2ⁿ。A(n,k) 比 C(n,k) 多乘了 k!，因为选出来还要排队。',
        en: 'Row n of Pascal’s triangle is the coefficient list of (x+1)ⁿ: C(n,k) counts choosing k of n. Each entry is the sum of the two above it, the row is symmetric and sums to 2ⁿ. A(n,k) is C(n,k) times k! because the chosen items can be ordered.',
      },
      chartLabel: { zh: 'C(n,k)', en: 'C(n,k)' },
      timeline: {
        zh: '动画：k 从 0 扫到目标 k，杨辉三角与系数柱同步高亮',
        en: 'Animation: k sweeps 0 → target, highlighting both Pascal’s triangle and the coefficient bars',
      },
      // 三角 + 柱状图是复合图，没有单一坐标系，自己排版（noAxes）
      noAxes: true,
      params: [
        { key: 'n', label: { zh: '行数 n', en: 'Row n' }, min: 3, max: 10, step: 1, init: 6, unit: '', digits: 0 },
        { key: 'k', label: { zh: '目标 k（超过 n 时截到 n）', en: 'Target k (clamped to n)' }, min: 0, max: 10, step: 1, init: 3, unit: '', digits: 0 },
      ],
      box(p) {
        const n = Math.max(1, Math.round(p.n));
        return { xMin: -1, xMax: n + 1, yMin: 0, yMax: 1 };
      },
      duration() {
        return 4.4;
      },
      state(t, p) {
        const n = Math.round(p.n);
        const row = binomialRow(n);
        const target = Math.min(Math.max(0, Math.round(p.k)), n);
        const total = this.duration(p);
        const tt = clamp(t, 0, total);
        const progress = total > 0 ? tt / total : 1;
        const k = Math.min(target, Math.round(target * progress));
        const coeff = row[k];
        const perm = binomialPerm(n, k);
        const totalSum = Math.pow(2, n);
        const half = Math.floor(n / 2);
        const maxCoeff = row[half];
        const maxText = n % 2 === 0 ? `C(${n},${half})` : `C(${n},${half}) = C(${n},${half + 1})`;
        const term = binomialTermText(n, k);

        const peakAt = n % 2 === 0 ? `${half}` : `${half}、${half + 1}`;
        const onPeak = k === half || (n % 2 === 1 && k === half + 1);
        let summary;
        if (onPeak) {
          summary =
            n % 2 === 0
              ? {
                  zh: `k = ${half} 正好是整行的对称中心：C(${n},${half}) = ${maxCoeff} 是最大系数，两边 C(${n},${half}±i) 成对相等。`,
                  en: `k = ${half} is the centre of the row: C(${n},${half}) = ${maxCoeff} is the largest coefficient and the entries pair up on both sides.`,
                }
              : {
                  zh: `n = ${n} 是奇数，中间两项 k = ${half} 与 ${half + 1} 并列最大，C(${n},${half}) = ${maxCoeff}，两边成对相等。`,
                  en: `With odd n = ${n} the two middle terms k = ${half} and ${half + 1} tie for the maximum, C(${n},${half}) = ${maxCoeff}, and the row mirrors around the centre.`,
                };
        } else if (k < half) {
          summary = {
            zh: `还没到中间：往右系数还在增大（C(n,k+1)/C(n,k) = (n−k)/(k+1) > 1），最大在 k = ${peakAt}。`,
            en: `Still left of the centre: the coefficients keep growing to the right (C(n,k+1)/C(n,k) = (n−k)/(k+1) > 1), peaking at k = ${peakAt}.`,
          };
        } else {
          summary = {
            zh: `越过中间后系数开始减小，但 C(${n},${k}) = C(${n},${n - k}) = ${coeff} 与对称位置相等；整行和 = 2^${n} = ${totalSum}。`,
            en: `Past the centre the coefficients shrink, but C(${n},${k}) = C(${n},${n - k}) = ${coeff} matches its mirror; the full row sums to 2^${n} = ${totalSum}.`,
          };
        }

        return {
          t: tt,
          n,
          k,
          row,
          coeff,
          perm,
          term,
          half,
          maxCoeff,
          maxText,
          totalSum,
          progress,
          summary,
          chartValue: coeff,
          rows: [
            { label: { zh: '当前 k', en: 'Current k' }, value: `k = ${k}` },
            { label: { zh: '组合数 C(n,k)', en: 'Combination C(n,k)' }, value: `C(${n},${k}) = ${coeff}` },
            { label: { zh: '排列数 A(n,k)', en: 'Permutation A(n,k)' }, value: `A(${n},${k}) = ${perm}` },
            { label: { zh: `(x+1)${binomialSup(n)} 中含 x${binomialSup(k)} 的项`, en: `Term in x${binomialSup(k)}` }, value: term },
            { label: { zh: '系数和 2ⁿ', en: 'Coefficient sum 2ⁿ' }, value: `2${binomialSup(n)} = ${totalSum}` },
            { label: { zh: '最大系数', en: 'Largest coefficient' }, value: `${maxText} = ${maxCoeff}` },
          ],
        };
      },
      draw(ctx, st, view, pal, opts, p) {
        const w = view.width;
        const h = view.height;
        const n = st.n;
        const row = st.row;
        const maxCoeff = Math.max(1, st.maxCoeff);
        const padX = w < 420 ? 18 : 28;
        const tight = h < 340;
        const triTop = 40;
        const triBottom = Math.round(h * (tight ? 0.44 : 0.5));
        const base = h - 30;
        const barsTop = Math.min(triBottom + 40, base - 70);

        // ---- 顶部标题 ----
        ctx.save();
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'left';
        ctx.font = `600 12px ${FONT_UI}`;
        ctx.fillStyle = pal.text;
        const titleText = L({ zh: '杨辉三角', en: 'Pascal’s triangle' });
        ctx.fillText(titleText, padX, 16);
        const titleW = ctx.measureText(titleText).width;
        ctx.font = `500 10px ${FONT_UI}`;
        ctx.fillStyle = pal.muted;
        ctx.textAlign = 'right';
        ctx.fillText(`${L({ zh: '系数和', en: 'row sum' })} 2${binomialSup(n)} = ${st.totalSum}`, w - padX, 16);
        ctx.textAlign = 'left';
        ctx.fillStyle = pal.muted;
        ctx.fillText(`(x + 1)${binomialSup(n)}`, padX + titleW + 14, 17);
        ctx.restore();

        // ---- 杨辉三角：行距、字号、横距 ----
        const triH = Math.max(40, triBottom - triTop);
        const rowsWanted = Math.max(3, Math.min(n + 1, Math.floor(triH / 15)));
        const startRow = n + 1 - rowsWanted;
        const dy = Math.min(40, triH / rowsWanted);
        const triOffset = Math.max(0, (triH - rowsWanted * dy) * 0.5);
        const dx = Math.min(46, (w - padX * 2 - 16) / Math.max(n, 1));
        const font = clamp(Math.min(dy * 0.52, dx * 0.5), 7.5, 12);
        const cx = w / 2;
        const rowY = (r) => triBottom - triOffset - (n - r) * dy - dy * 0.5;

        if (startRow > 0) {
          ctx.save();
          ctx.font = `600 ${font}px ${FONT_UI}`;
          ctx.fillStyle = pal.muted;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText('⋮', cx, rowY(startRow) - dy * 0.9);
          ctx.restore();
        }

        const triangle = [];
        for (let r = 0; r <= n; r += 1) triangle.push(binomialRow(r));
        for (let r = Math.max(0, startRow); r <= n; r += 1) {
          const y = rowY(r);
          const isLast = r === n;
          if (isLast) {
            const halfW = (r * dx) / 2 + dx * 0.56;
            ctx.save();
            ctx.fillStyle = pal.area;
            roundRect(ctx, cx - halfW, y - dy * 0.38, halfW * 2, dy * 0.76, 6);
            ctx.fill();
            ctx.restore();
          }
          ctx.save();
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.font = `${isLast ? 600 : 500} ${isLast ? font : font * 0.92}px ${FONT_UI}`;
          for (let c = 0; c <= r; c += 1) {
            const x = cx + (c - r / 2) * dx;
            if (isLast && c === st.k) {
              const boxW = Math.max(font * 2.1, 22);
              const boxH = font * 1.5;
              ctx.fillStyle = pal.point;
              roundRect(ctx, x - boxW / 2, y - boxH / 2, boxW, boxH, boxH / 2);
              ctx.fill();
              ctx.fillStyle = pal.dot;
            } else {
              ctx.fillStyle = isLast ? pal.text : pal.muted;
            }
            ctx.fillText(String(triangle[r][c]), x, y + 0.5);
          }
          ctx.restore();
        }

        // ---- 柱状图标题 ----
        ctx.save();
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'left';
        ctx.font = `500 10px ${FONT_UI}`;
        ctx.fillStyle = pal.muted;
        ctx.fillText(L({ zh: '二项式系数 C(n,k)', en: 'Binomial coefficients C(n,k)' }), padX, barsTop - 14);
        if (w >= 470) {
          ctx.textAlign = 'right';
          ctx.fillStyle = pal.point;
          ctx.fillText(`${L({ zh: '当前项', en: 'term' })} ${st.term}`, w - padX, barsTop - 14);
        }
        ctx.restore();

        // ---- 柱状图 ----
        const barLeft = padX + 6;
        const barRight = w - padX;
        const step = Math.max(6, (barRight - barLeft) / (n + 1));
        const barW = Math.max(4, step * 0.68);
        const barArea = Math.max(30, base - barsTop);
        ctx.save();
        ctx.strokeStyle = pal.axis;
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.moveTo(barLeft, base);
        ctx.lineTo(barRight, base);
        ctx.stroke();
        ctx.restore();

        for (let k = 0; k <= n; k += 1) {
          const left = barLeft + k * step + (step - barW) / 2;
          const hgt = Math.max(row[k] > 0 ? 1.5 : 0, (row[k] / maxCoeff) * barArea);
          ctx.save();
          ctx.fillStyle = k === st.k ? pal.point : pal.curve;
          ctx.globalAlpha = k === st.k ? 1 : 0.38;
          ctx.fillRect(left, base - hgt, barW, hgt);
          ctx.restore();
        }

        // 最大系数的柱子用虚线框提示
        if (st.k !== st.half) {
          const left = barLeft + st.half * step + (step - barW) / 2;
          ctx.save();
          ctx.strokeStyle = pal.curve3;
          ctx.lineWidth = 1.2;
          ctx.setLineDash([3, 3]);
          ctx.strokeRect(left, base - barArea, barW, barArea);
          ctx.restore();
        }

        // 当前柱描边
        {
          const left = barLeft + st.k * step + (step - barW) / 2;
          const hgt = Math.max(1.5, (row[st.k] / maxCoeff) * barArea);
          ctx.save();
          ctx.strokeStyle = pal.tangent;
          ctx.lineWidth = 1.4;
          ctx.strokeRect(left, base - hgt, barW, hgt);
          ctx.restore();
        }

        // ---- 柱顶数值与底部 k 刻度 ----
        ctx.save();
        ctx.textAlign = 'center';
        ctx.textBaseline = 'bottom';
        ctx.font = `500 9.5px ${FONT_UI}`;
        for (let k = 0; k <= n; k += 1) {
          const centre = barLeft + k * step + step / 2;
          const showValue = step >= 26 || k === st.k || k === st.half;
          if (showValue) {
            ctx.fillStyle = k === st.k ? pal.tangent : pal.muted;
            ctx.fillText(String(row[k]), centre, base - Math.max(1.5, (row[k] / maxCoeff) * barArea) - 4);
          }
        }
        ctx.textBaseline = 'top';
        ctx.font = `500 10px ${FONT_UI}`;
        const every = step >= 19 ? 1 : Math.ceil(19 / step);
        for (let k = 0; k <= n; k += 1) {
          if (k % every !== 0 && k !== n && k !== st.k) continue;
          ctx.fillStyle = k === st.k ? pal.tangent : pal.muted;
          ctx.fillText(String(k), barLeft + k * step + step / 2, base + 7);
        }
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'left';
        ctx.font = `600 10px ${FONT_UI}`;
        ctx.fillStyle = pal.muted;
        ctx.fillText('k', barRight + 3, base + 12);
        ctx.restore();
      },
    });

    defineLesson('binomial', {
      lesson: {
        zh: '杨辉三角的每一行就是 (x+1)ⁿ 展开式的系数。行的第 k 个数是 C(n,k) = n!/(k!(n−k)!)，它数的是“从 n 个里选出 k 个”的方案数；如果选出来还要排队，就再乘 k!，得到排列数 A(n,k) = n!/(n−k)!。整行关于中间对称，因为“选 k 个”和“留 n−k 个”是一一对应的；整行加起来是 2ⁿ。',
        en: 'Each row of Pascal’s triangle lists the coefficients of (x+1)ⁿ. The k-th entry is C(n,k) = n!/(k!(n−k)!), the number of ways to choose k of n; if the chosen items are then ordered, multiply by k! to get A(n,k) = n!/(n−k)!. The row is symmetric because choosing k is the same as leaving n−k, and the row sums to 2ⁿ.',
      },
      steps: [
        { at: 0, zh: 'k = 0 时只有“一个都不选”这一种方案，C(n,0) = 1，柱子最矮；三角每行两端的 1 就是这个意思。', en: 'At k = 0 there is only the empty choice, C(n,0) = 1 — the shortest bar and the 1 at each end of the triangle.' },
        { at: 0.28, zh: 'k 增大，C(n,k) 迅速变大：从 n 个里选 k 个的方案数在中间最多。每个数都是肩上两数之和。', en: 'As k grows, C(n,k) grows fast: the number of k-subsets is largest in the middle. Each entry is the sum of the two above it.' },
        { at: 0.6, zh: '峰在 k = ⌊n/2⌋ 处；n 为奇数时中间两个数相等，因此柱状图有两个一样高的峰。', en: 'The peak is at k = ⌊n/2⌋; for odd n the two middle entries are equal, so the bars have two equal peaks.' },
        { at: 0.85, zh: '过峰后系数成对下降：C(n,k) = C(n,n−k)。整行和 = (1+1)ⁿ = 2ⁿ，这也解释了二项式系数之和。', en: 'Past the peak the coefficients fall in mirror pairs: C(n,k) = C(n,n−k). The row sums to (1+1)ⁿ = 2ⁿ, which is why the binomial coefficients add up to 2ⁿ.' },
      ],
    });

