        source: { zh: '高考题型 · 改编', en: 'Exam-style · adapted' },
        tag: { zh: '定积分 · 三角', en: 'Trigonometric integral' },
        params: { fn: 'sin', b: Math.PI / 2 },
        stem: { zh: '计算 ∫₀^(π/2) sin x dx。', en: 'Evaluate ∫₀^(π/2) sin x dx.' },
