    // ---- src/models/lineCircle.js -----------------------------------
    // ---------------------------------------------------------------------------
    // 模型 C1 · 直线与圆（高二：d、弦长、相切条件）
    // ---------------------------------------------------------------------------

    /** 斜截式 y = kx + b 的文字形式：省略系数 1，b = 0 时不写 */
    function lcLineText(k, b) {
      const parts = [];
      if (Math.abs(k) > 1e-9) {
        const coef = Math.abs(Math.abs(k) - 1) < 1e-9 ? '' : fnum(Math.abs(k), 2);
        parts.push(`${k < 0 ? '−' : ''}${coef}x`);
      }
      const absB = Math.abs(b);
      if (absB > 1e-9) {
        parts.push(parts.length ? `${b < 0 ? '−' : '+'} ${fnum(absB, 2)}` : `${b < 0 ? '−' : ''}${fnum(absB, 2)}`);
      } else if (!parts.length) {
        parts.push('0');
      }
      return `y = ${parts.join(' ')}`;
    }

    defineModel({
      id: 'lineCircle',
      grade: 2,
      name: { zh: '直线与圆', en: 'Line and circle' },
      formula: {
        zh: 'd = |b| / √(1 + k²)　　弦长 = 2√(r² − d²)　　相切 ⇔ d = r',
        en: 'd = |b|/√(1+k²)　chord = 2√(r²−d²)　tangent ⇔ d = r',
      },
      hint: {
        zh: '把几何问题化成一串数：圆心到直线的距离 d 与半径 r 一比，位置关系就定了。相交时弦心距 d、半弦长 √(r² − d²)、半径 r 组成直角三角形，所以弦长公式其实是勾股定理。',
        en: 'One comparison settles everything: the distance d from the centre to the line against the radius r. When they cross, d, half the chord √(r²−d²) and r form a right triangle — the chord formula is just Pythagoras.',
      },
      chartLabel: { zh: '弦长', en: 'Chord' },
      timeline: {
        zh: '动画：直线平行移动，d 由 1.3r 连续减到 0（相离 → 相切 → 相交）',
        en: 'Animation: the line slides in, d falls from 1.3r to 0 (apart → tangent → secant)',
      },
      params: [
        { key: 'r', label: { zh: '半径 r', en: 'Radius r' }, min: 1, max: 5, step: 0.1, init: 4, unit: '', digits: 1 },
        { key: 'k', label: { zh: '直线斜率 k', en: 'Slope k' }, min: -3, max: 3, step: 0.1, init: 1, unit: '', digits: 1 },
      ],

      /** 只依赖参数的量：圆、直线的法向/方向、动画起点 */
      derive(p) {
        const r = Math.max(0.2, Number(p.r) || 0.2);
        const k = Number(p.k) || 0;
        const s = Math.hypot(1, k);
        return {
          r,
          k,
          s,
          d0: 1.3 * r,
          // 直线 y = kx + b 的单位法向 n = (k, −1)/s；圆心到直线的垂足 = −(b/s)·n
          nx: k / s,
          ny: -1 / s,
          ux: 1 / s,
          uy: k / s,
        };
      },

      /** 某一时刻的几何：t 是秒 */
      frame(t, p) {
        const g = this.derive(p);
        const total = this.duration(p);
        const u = clamp(t / total, 0, 1);
        const d = g.d0 * (1 - u);
        const b = d * g.s;
        const inside = d < g.r - 1e-9;
        const chord = inside ? 2 * Math.sqrt(Math.max(0, g.r * g.r - d * d)) : 0;
        const near = Math.abs(d - g.r) <= 0.03 * g.r;
        return {
          ...g,
          t,
          u,
          d,
          b,
          inside,
          near,
          chord,
          Hx: -g.nx * (b / g.s),
          Hy: -g.ny * (b / g.s),
        };
      },

      box(p) {
        const g = this.derive(p);
        // 上边留出 1.6 给方程文字（t = 0 时直线恰好在上方 1.3r 处），下边只留贴边余量
        return {
          xMin: -(g.r + 2.4),
          xMax: g.r + 2.4,
          yMin: -(g.r + 1.2),
          yMax: 1.3 * g.r + 1.6,
        };
      },

      duration() {
        return 6;
      },

      state(t, p) {
        const f = this.frame(t, p);
        const relation = f.near
          ? L({ zh: '相切', en: 'tangent' })
          : f.inside
            ? L({ zh: '相交', en: 'secant' })
            : L({ zh: '相离', en: 'disjoint' });

        let summary;
        if (f.near) {
          summary = {
            zh: `d = r = ${fnum(f.r, 2)}：直线与圆相切，公共点只有切点 H，此时弦长退化为 0。`,
            en: `d = r = ${fnum(f.r, 2)}: tangent — the only common point is H, and the chord collapses to 0.`,
          };
        } else if (f.inside) {
          summary = {
            zh: `d = ${fnum(f.d, 2)} < r = ${fnum(f.r, 2)}：相交，弦长 = 2√(r² − d²) = ${fnum(f.chord, 2)}；d、半弦长、r 构成直角三角形。`,
            en: `d = ${fnum(f.d, 2)} < r = ${fnum(f.r, 2)}: secant, chord = 2√(r²−d²) = ${fnum(f.chord, 2)}; d, half-chord and r form a right triangle.`,
          };
        } else {
          summary = {
            zh: `d = ${fnum(f.d, 2)} > r = ${fnum(f.r, 2)}：相离，直线与圆没有公共点，没有弦。`,
            en: `d = ${fnum(f.d, 2)} > r = ${fnum(f.r, 2)}: disjoint — no common point, no chord.`,
          };
        }

        return {
          t: f.t,
          r: f.r,
          k: f.k,
          b: f.b,
          d: f.d,
          chord: f.chord,
          inside: f.inside,
          near: f.near,
          Hx: f.Hx,
          Hy: f.Hy,
          nx: f.nx,
          ny: f.ny,
          ux: f.ux,
          uy: f.uy,
          summary,
          chartValue: f.chord,
          rows: [
            { label: { zh: '圆心到直线 d', en: 'Distance d' }, value: fnum(f.d, 2) },
            { label: { zh: '半径 r', en: 'Radius r' }, value: fnum(f.r, 2) },
            { label: { zh: '位置关系', en: 'Relation' }, value: relation },
            {
              label: { zh: '弦长 2√(r² − d²)', en: 'Chord 2√(r²−d²)' },
              value: f.inside ? fnum(f.chord, 2) : '—',
            },
            { label: { zh: '直线截距 b', en: 'Intercept b' }, value: fnum(f.b, 2) },
            { label: { zh: '直线方程', en: 'Line' }, value: lcLineText(f.k, f.b) },
          ],
        };
      },

      draw(ctx, st, view, pal, opts, p) {
        const r = st.r;
        const H = { x: st.Hx, y: st.Hy };
        const n = { x: st.nx, y: st.ny };
        const u = { x: st.ux, y: st.uy };
        // 半径 r 与 d 共线反向：可以直接用眼比较 d 与 r
        const R = { x: n.x * r, y: n.y * r };

        // 圆
        circleWorld(ctx, view, 0, 0, r, pal.curve, 2.4);

        // 半径（虚线）：只写记号 r，数值放到角落读数里，避免和坐标刻度撞
        segmentWorld(ctx, view, 0, 0, R.x, R.y, pal.curve3, 1.8, [6, 4]);
        labelWorld(ctx, view, 'r', R.x * 0.55 + 12 / view.scale, R.y * 0.55 + 12 / view.scale, pal.curve3, 'left', 11);

        // 直线
        lineThroughWorld(ctx, view, 0, st.b, 1, st.k, pal.curve2, 2.2);

        // 圆心到直线的垂线（弦心距 d）
        if (st.d > 1e-6) {
          segmentWorld(ctx, view, 0, 0, H.x, H.y, pal.point, 2, [4, 4]);
          rightAngle(ctx, view, H.x, H.y, n.x, n.y, u.x, u.y, pal.muted, 9);
          dotWorld(ctx, view, H.x, H.y, pal.point, 3.6);
          labelWorld(ctx, view, 'd', H.x * 0.5 + 12 / view.scale, H.y * 0.5 + 12 / view.scale, pal.point, 'left', 11);
          labelWorld(ctx, view, 'H', H.x - u.x * 0.34, H.y - u.y * 0.34, pal.point, 'right', 10);
        }

        // 弦
        if (st.inside) {
          const half = st.chord / 2;
          const A = { x: H.x - u.x * half, y: H.y - u.y * half };
          const B = { x: H.x + u.x * half, y: H.y + u.y * half };
          segmentWorld(ctx, view, A.x, A.y, B.x, B.y, pal.tangent, 3);
          dotWorld(ctx, view, A.x, A.y, pal.tangent, 3.4);
          dotWorld(ctx, view, B.x, B.y, pal.tangent, 3.4);
        }

        // 相切时把切点圈出来
        if (st.near) {
          circleWorld(ctx, view, H.x, H.y, 0.2, pal.tangent, 1.8);
          labelWorld(ctx, view, L({ zh: '切点', en: 'tangent point' }), H.x - u.x * 0.42, H.y - u.y * 0.42, pal.tangent, 'right', 10);
        }

        // 角落：圆的方程、直线方程、位置关系
        const cornerX = view.x0 + (view.x1 - view.x0) * 0.03;
        const top = view.y1 - 0.45;
        labelWorld(ctx, view, `x² + y² = ${fnum(r * r, 2)}`, cornerX, top, pal.text, 'left', 11);
        labelWorld(ctx, view, lcLineText(st.k, st.b), cornerX, top - 0.65, pal.curve2, 'left', 11);

        const rel = st.near
          ? { zh: `相切 · d = r = ${fnum(r, 2)}`, en: `tangent · d = r = ${fnum(r, 2)}` }
          : st.inside
            ? { zh: `相交 · d = ${fnum(st.d, 2)} · 弦长 ${fnum(st.chord, 2)}`, en: `secant · d = ${fnum(st.d, 2)} · chord ${fnum(st.chord, 2)}` }
            : { zh: `相离 · d = ${fnum(st.d, 2)} > r = ${fnum(r, 2)}`, en: `disjoint · d = ${fnum(st.d, 2)} > r = ${fnum(r, 2)}` };
        labelWorld(
          ctx,
          view,
          L(rel),
          view.x0 + (view.x1 - view.x0) * 0.03,
          view.y0 + (view.y1 - view.y0) * 0.08,
          st.near ? pal.tangent : st.inside ? pal.curve : pal.muted,
          'left',
          11,
        );
      },
    });

    defineLesson('lineCircle', {
      lesson: {
        zh: '判断直线与圆的位置关系，不用解方程组：把圆心到直线的距离 d 与半径 r 比大小即可。直线 l: y = kx + b 写成 kx − y + b = 0，由点到直线距离公式 d = |b| / √(k² + 1)。d > r 相离、d = r 相切、d < r 相交。相交时，圆心到弦的垂线平分弦，半弦长、d、r 组成直角三角形，于是弦长 = 2√(r² − d²)。',
        en: 'You do not need to solve the system: compare the distance d from the centre to the line with the radius r. For l: y = kx + b, i.e. kx − y + b = 0, d = |b|/√(k²+1). d > r no intersection, d = r tangent, d < r secant. When secant, the perpendicular from the centre bisects the chord, and half-chord, d and r form a right triangle, so chord = 2√(r²−d²).',
      },
      steps: [
        {
          at: 0,
          zh: '直线还在圆外：d 比 r 大，整条直线离圆心都超过 r，与圆没有公共点（相离）。',
          en: 'The line is still outside: d exceeds r, every point of the line is farther than r from the centre — no common point (disjoint).',
        },
        {
          at: 0.24,
          zh: 'd 减小到正好等于 r：直线与圆只有一个公共点，这就是相切，垂足 H 就是切点，半径 OH ⊥ 直线。',
          en: 'As d reaches exactly r the line touches the circle at one point — tangent. The foot H is the point of tangency and OH ⊥ l.',
        },
        {
          at: 0.55,
          zh: 'd < r：直线穿过圆，得到一条弦。垂足 H 是弦的中点，半弦长 = √(r² − d²)，这也是弦长公式的来源。',
          en: 'With d < r the line cuts the circle in a chord. H is its midpoint and half-chord = √(r²−d²) — that is where the chord formula comes from.',
        },
        {
          at: 0.9,
          zh: 'd → 0 时直线过圆心，弦变成直径，弦长取到最大值 2r；这也说明弦长随 d 增大而变短。',
          en: 'As d → 0 the line passes through the centre, the chord becomes a diameter of length 2r: the chord shrinks as d grows.',
        },
      ],
    });

    defineQuiz('lineCircle', (rng) => {
      const r = rnum(rng, 2, 5, 0.5);
      const k = rnum(rng, -2, 2, 0.5);
      const s = Math.sqrt(1 + k * k);
      const pick1 = Math.floor(rng() * 4);

      if (pick1 === 0) {
        const b = r * s;
        return makeQuiz(
          { r, k },
          {
            zh: `圆 x² + y² = ${fnum(r * r, 2)} 与直线 y = ${fnum(k, 1)}x + b 相切，求 b 的值（取正值）。`,
            en: `The line y = ${fnum(k, 1)}x + b is tangent to x² + y² = ${fnum(r * r, 2)}. Find b (take the positive value).`,
          },
          '',
          b,
          {
            zh: `相切 ⇔ d = r，而 d = |b| / √(1 + k²)，所以 b = r√(1 + k²) = ${fnum(r, 2)} × ${fnum(s, 4)} = ${fnum(b, 2)}。`,
            en: `Tangent ⇔ d = r with d = |b|/√(1+k²), so b = r√(1+k²) = ${fnum(b, 2)}.`,
          },
          0.02,
        );
      }
      if (pick1 === 1) {
        const b0 = rnum(rng, 0.4 * r, 1.2 * r, 0.5);
        const d = Math.abs(b0) / s;
        return makeQuiz(
          { r, k },
          {
            zh: `圆 x² + y² = ${fnum(r * r, 2)}，直线 y = ${fnum(k, 1)}x + ${fnum(b0, 1)}，求圆心到这条直线的距离 d。`,
            en: `For the circle x² + y² = ${fnum(r * r, 2)} and the line y = ${fnum(k, 1)}x + ${fnum(b0, 1)}, find the distance d from the centre to the line.`,
          },
          '',
          d,
          {
            zh: `d = |b| / √(1 + k²) = ${fnum(Math.abs(b0), 1)} / ${fnum(s, 4)} = ${fnum(d, 3)}。`,
            en: `d = |b|/√(1+k²) = ${fnum(Math.abs(b0), 1)}/${fnum(s, 4)} = ${fnum(d, 3)}.`,
          },
          0.02,
        );
      }
      if (pick1 === 2) {
        const kk = Math.abs(k) < 0.5 ? 0.5 : k;
        const ss = Math.sqrt(1 + kk * kk);
        const b0 = rnum(rng, 0.3 * r, 0.95 * r, 0.5);
        const d = Math.abs(b0) / ss;
        const chord = 2 * Math.sqrt(Math.max(0, r * r - d * d));
        return makeQuiz(
          { r, k: kk },
          {
            zh: `圆 x² + y² = ${fnum(r * r, 2)} 被直线 y = ${fnum(kk, 1)}x + ${fnum(b0, 1)} 截得一条弦，求弦长。`,
            en: `The line y = ${fnum(kk, 1)}x + ${fnum(b0, 1)} cuts x² + y² = ${fnum(r * r, 2)} in a chord. Find its length.`,
          },
          '',
          chord,
          {
            zh: `先求 d = ${fnum(Math.abs(b0), 1)}/√(1 + ${fnum(kk * kk, 2)}) = ${fnum(d, 3)}，再代弦长公式 2√(r² − d²) = 2√(${fnum(
              r * r,
              2,
            )} − ${fnum(d * d, 2)}) = ${fnum(chord, 3)}。`,
            en: `d = ${fnum(d, 3)}, then chord = 2√(r²−d²) = ${fnum(chord, 3)}.`,
          },
          0.02,
        );
      }
      const y0 = r / s;
      return makeQuiz(
        { r, k },
        {
          zh: `圆 x² + y² = ${fnum(r * r, 2)} 的一条切线斜率为 ${fnum(k, 1)}，求切点的纵坐标（取正值）。`,
          en: `A tangent to x² + y² = ${fnum(r * r, 2)} has slope ${fnum(k, 1)}. Find the y-coordinate of the point of tangency (positive).`,
        },
        '',
        y0,
        {
          zh: `切点就是圆心到直线的垂足，且 |OH| = r。切线 y = kx + b 满足 b = r√(1 + k²)，垂足 H = (−kb/(1 + k²), b/(1 + k²))，故 y = b/(1 + k²) = r/√(1 + k²) = ${fnum(y0, 3)}。`,
          en: `The tangent point is the foot from the centre with |OH| = r. With b = r√(1+k²), its y-coordinate is b/(1+k²) = r/√(1+k²) = ${fnum(y0, 3)}.`,
        },
        0.02,
      );
    });

    defineExams([
      {
        id: 'ex-lineCircle-1',
        modelId: 'lineCircle',
        source: { zh: '高考题型 · 改编', en: 'Exam-style · adapted' },
        tag: { zh: '弦长', en: 'Chord length' },
        params: { r: 5, k: -0.75 },
        stem: {
          zh: '已知圆 x² + y² = 25 与直线 3x + 4y − 5 = 0，求这条直线被圆截得的弦长。',
          en: 'The line 3x + 4y − 5 = 0 meets the circle x² + y² = 25 in a chord. Find its length.',
        },
        unit: '',
        answer: 4 * Math.sqrt(6),
        tol: 0.01,
        solution: {
          zh: '圆心到直线的距离 d = |−5| / √(3² + 4²) = 5/5 = 1，半径 r = 5。半弦长 = √(r² − d²) = √(25 − 1) = 2√6，所以弦长 = 4√6 ≈ 9.80。',
          en: 'd = |−5|/√(3²+4²) = 1 and r = 5, so half-chord = √(25−1) = 2√6 and the chord is 4√6 ≈ 9.80.',
        },
      },
      {
        id: 'ex-lineCircle-2',
        modelId: 'lineCircle',
        source: { zh: '高考题型 · 改编', en: 'Exam-style · adapted' },
        tag: { zh: '相切条件', en: 'Tangency' },
        params: { r: 5, k: 2 },
        stem: {
          zh: '求斜率为 2 且与圆 x² + y² = 25 相切的直线在 y 轴上的截距（取正值）。',
          en: 'A line of slope 2 is tangent to x² + y² = 25. Find its y-intercept (positive value).',
        },
        unit: '',
        answer: 5 * Math.sqrt(5),
        tol: 0.01,
        solution: {
          zh: '设直线 y = 2x + b，相切要求 d = |b|/√(1 + 2²) = 5，故 |b| = 5√5，取正值 b = 5√5 ≈ 11.18。',
          en: 'Write the line as y = 2x + b; tangency means |b|/√5 = 5, so b = 5√5 ≈ 11.18.',
        },
      },
    ]);

    // ---- src/models/linearProgramming.js ----------------------------
    // ---------------------------------------------------------------------------
    // 模型 · 线性规划（高三）
    // ---------------------------------------------------------------------------

    /** 约束固定：x ≥ 0、y ≥ 0、x + y ≤ 6、2x + y ≤ 8 → 可行域是四边形 OABC */
    function linearVertices() {
      return [
        { name: 'O', x: 0, y: 0 },
        { name: 'A', x: 0, y: 6 },
        { name: 'B', x: 2, y: 4 },
        { name: 'C', x: 4, y: 0 },
      ];
    }

    /** 可行域（逆时针）：O → C → B → A */
    function linearRegion() {
      return [[0, 0], [4, 0], [2, 4], [0, 6]];
    }

    /** 目标函数 z = c1·x + c2·y */
    function linearObjective(c1, c2, x, y) {
      return c1 * x + c2 * y;
    }

    /** 目标函数表达式：z = 2x + 3y（省略 1、0，负号用 −） */
    function linearExpr(c1, c2) {
      const parts = [];
      const coef = (v) => (Math.abs(Math.abs(v) - 1) < 1e-9 ? '' : fnum(Math.abs(v), 1));
      const sign = (v) => (parts.length === 0 ? (v < 0 ? '−' : '') : v < 0 ? ' − ' : ' + ');
      if (Math.abs(c1) > 1e-9) parts.push(`${sign(c1)}${coef(c1)}x`);
      if (Math.abs(c2) > 1e-9) parts.push(`${sign(c2)}${coef(c2)}y`);
      if (!parts.length) return 'z = 0';
      return `z = ${parts.join('')}`;
    }

    defineModel({
      id: 'linearProgramming',
      grade: 3,
      name: { zh: '线性规划', en: 'Linear programming' },
      formula: {
        zh: 'z = c₁x + c₂y　约束：x ≥ 0，y ≥ 0，x + y ≤ 6，2x + y ≤ 8',
        en: 'z = c₁x + c₂y s.t. x ≥ 0, y ≥ 0, x + y ≤ 6, 2x + y ≤ 8',
      },
      hint: {
        zh: '先画出可行域（四个不等式交出的凸四边形），再把目标函数看作一族平行等值线 c₁x + c₂y = z。等值线平移时 z 在变，最后与可行域只剩一个公共点的位置就是最优解——它一定落在某个顶点上，所以只要比较四个顶点的 z 值。',
        en: 'Draw the feasible region first (the convex quadrilateral cut out by the four inequalities), then read z = c₁x + c₂y as a family of parallel level lines. Sliding the line changes z; the last line that still touches the region gives the optimum, and it always happens at a vertex — so just compare the four vertex values.',
      },
      chartLabel: { zh: '等值线 z', en: 'level z' },
      timeline: {
        zh: '动画：等值线扫过可行域，最后停在最优顶点',
        en: 'Animation: the level line sweeps the region and stops on the optimal vertex',
      },
      params: [
        { key: 'c1', label: { zh: '目标函数 x 的系数 c₁', en: 'Coefficient c₁ of x' }, min: -3, max: 3, step: 0.1, init: 2, unit: '', digits: 1 },
        { key: 'c2', label: { zh: '目标函数 y 的系数 c₂', en: 'Coefficient c₂ of y' }, min: -3, max: 3, step: 0.1, init: 3, unit: '', digits: 1 },
        {
          key: 'goal',
          label: { zh: '求', en: 'Goal' },
          kind: 'select',
          init: 'max',
          options: [
            { value: 'max', label: { zh: '最大值', en: 'Maximum' } },
            { value: 'min', label: { zh: '最小值', en: 'Minimum' } },
          ],
        },
      ],
      box() {
        return { xMin: -3, xMax: 7, yMin: -0.4, yMax: 6.4 };
      },
      duration() {
        return 5;
      },
      state(t, p) {
        const c1 = Number(p.c1) || 0;
        const c2 = Number(p.c2) || 0;
        const goal = p.goal === 'min' ? 'min' : 'max';
        const isMax = goal === 'max';
        const verts = linearVertices().map((v) => ({
          name: v.name,
          x: v.x,
          y: v.y,
          z: linearObjective(c1, c2, v.x, v.y),
        }));
        const zs = verts.map((v) => v.z);
        const zMin = Math.min.apply(null, zs);
        const zMax = Math.max.apply(null, zs);
        const degenerate = Math.abs(c1) < 1e-9 && Math.abs(c2) < 1e-9;
        const tol = 1e-9;
        const best = verts.filter((v) => Math.abs(v.z - (isMax ? zMax : zMin)) <= tol);
        const other = verts.filter((v) => Math.abs(v.z - (isMax ? zMin : zMax)) <= tol);
        const total = this.duration(p);
        const tt = clamp(t, 0, total);
        const progress = total > 0 ? tt / total : 1;
        const level = isMax ? zMin + (zMax - zMin) * progress : zMax - (zMax - zMin) * progress;
        const bestText = degenerate
          ? L({ zh: '任一点', en: 'any point' })
          : best.map((v) => `${v.name}(${v.x}, ${v.y})`).join(L({ zh: ' 与 ', en: ' & ' }));
        const bestValue = isMax ? zMax : zMin;
        const otherValue = isMax ? zMin : zMax;
        const bestName = isMax ? 'z_max' : 'z_min';

        let summary;
        if (degenerate) {
          summary = {
            zh: 'c₁ = c₂ = 0 时目标函数恒等于 0：可行域里每个点的 z 都一样，没有唯一最优解。',
            en: 'With c₁ = c₂ = 0 the objective is identically 0: every point of the region has the same z, so there is no unique optimum.',
          };
        } else if (best.length > 1) {
          summary = {
            zh: `等值线与可行域的一条边平行，${bestText} 并列取到 ${bestName} = ${fnum(bestValue, 2)}，整条边上的点都是最优解。`,
            en: `The level lines are parallel to an edge, so ${bestText} tie for ${bestName} = ${fnum(bestValue, 2)}: every point on that edge is optimal.`,
          };
        } else {
          const tail = progress > 0.995
            ? { zh: `等值线 z = ${fnum(level, 2)} 已经停在最优顶点上。`, en: `The level line z = ${fnum(level, 2)} now rests on the optimal vertex.` }
            : { zh: `等值线 z = ${fnum(level, 2)} 正在平移。`, en: `The level line z = ${fnum(level, 2)} is sliding across.` };
          summary = {
            zh: `比较四个顶点：${bestName} = ${fnum(bestValue, 2)}（顶点 ${bestText}），另一头是 ${fnum(otherValue, 2)}（${other.map((v) => v.name).join('/')}）。${tail.zh}`,
            en: `Compare the vertices: ${bestName} = ${fnum(bestValue, 2)} at ${bestText}, while the other extreme is ${fnum(otherValue, 2)} at ${other.map((v) => v.name).join('/')}. ${tail.en}`,
          };
        }

        const rows = [
          {
            label: { zh: '目标函数', en: 'Objective' },
            value: `${linearExpr(c1, c2)} → ${isMax ? 'max' : 'min'}`,
          },
        ];
        verts.forEach((v) => {
          rows.push({
            label: { zh: `顶点 ${v.name}(${v.x}, ${v.y})`, en: `Vertex ${v.name}(${v.x}, ${v.y})` },
            value: `z = ${fnum(v.z, 2)}`,
          });
        });
        rows.push({
          label: isMax
            ? { zh: '最优解（使 z 最大）', en: 'Optimal vertex (max z)' }
            : { zh: '最优解（使 z 最小）', en: 'Optimal vertex (min z)' },
          value: bestText,
        });
        rows.push({
          label: isMax ? { zh: '最优值 z_max', en: 'Optimal value z_max' } : { zh: '最优值 z_min', en: 'Optimal value z_min' },
          value: fnum(bestValue, 2),
        });

        return {
          t: tt,
          c1,
          c2,
          goal,
          isMax,
          expr: linearExpr(c1, c2),
          verts,
          zMin,
          zMax,
          level,
          progress,
          best,
          degenerate,
          bestValue,
          bestText,
          chartValue: isFinite(level) ? level : 0,
          summary,
          rows,
        };
      },
      draw(ctx, st, view, pal, opts, p) {
        const c1 = st.c1;
        const c2 = st.c2;

        // ---- 可行域 ----
        const region = linearRegion();
        regionWorld(ctx, view, region, pal.area);
        polylineWorld(ctx, view, region.concat([region[0]]), pal.curve, 2.2);
        tag(
          ctx,
          L({ zh: '可行域', en: 'feasible region' }),
          view.toX(1.05),
          view.toY(2.2),
          pal.muted,
          'center',
          10,
        );

        // ---- 约束边界（延长到画面外） ----
        lineThroughWorld(ctx, view, 0, 6, 1, -1, pal.curve2, 1.6, [6, 4]);
        lineThroughWorld(ctx, view, 4, 0, 1, -2, pal.curve3, 1.6, [6, 4]);
        tag(ctx, 'x + y = 6', view.toX(4.75) + 6, view.toY(1.25) - 6, pal.curve2, 'left', 10);
        tag(ctx, '2x + y = 8', view.toX(3.3) + 6, view.toY(1.4) - 8, pal.curve3, 'left', 10);

        // ---- 等值线：先画 z_min / z_max 的参考线，再画当前线 ----
        if (!st.degenerate) {
          const dirX = c2;
          const dirY = -c1;
          const anchor = (m) => (Math.abs(c2) > Math.abs(c1) ? [0, m / c2] : [m / c1, 0]);
          [st.zMin, st.zMax].forEach((m) => {
            const a = anchor(m);
            lineThroughWorld(ctx, view, a[0], a[1], dirX, dirY, pal.muted, 1, [3, 5]);
          });
          const cur = anchor(st.level);
          lineThroughWorld(ctx, view, cur[0], cur[1], dirX, dirY, pal.tangent, 2.3, [7, 4]);
          // 等值线读数挂在右上角：贴在线上放容易和 y 轴名、约束式标签打架
          tag(
            ctx,
            `${L({ zh: '等值线', en: 'level' })} z = ${fnum(st.level, 2)}`,
            view.width - 14,
            14,
            pal.tangent,
            'right',
            10,
          );
        }

        // ---- 顶点 ----
        const offsets = {
          O: { dx: -10, dy: 17, align: 'right' },
          A: { dx: -10, dy: -15, align: 'right' },
          B: { dx: 11, dy: -15, align: 'left' },
          C: { dx: 11, dy: 17, align: 'left' },
        };
        st.verts.forEach((v) => {
          const isBest = !st.degenerate && Math.abs(v.z - st.bestValue) <= 1e-9;
          const px = view.toX(v.x);
          const py = view.toY(v.y);
          if (isBest) circleWorld(ctx, view, v.x, v.y, 9 / view.scale, pal.point, 1.8);
          dotWorld(ctx, view, v.x, v.y, isBest ? pal.point : pal.text, isBest ? 5 : 3.4);
          const off = offsets[v.name] || { dx: 8, dy: -12, align: 'left' };
          tag(
            ctx,
            `${v.name}(${v.x}, ${v.y})  z=${fnum(v.z, 2)}`,
            px + off.dx,
            py + off.dy,
            isBest ? pal.point : pal.muted,
            off.align,
            10,
          );
        });

        // ---- 最优解角标 ----
        const bestOne = st.best && st.best.length ? st.best[0] : null;
        if (bestOne && !st.degenerate) {
          const px = view.toX(bestOne.x);
          const py = view.toY(bestOne.y);
          // 角标往可行域外侧放：A/B 在上方，O 在右下，C 在下方（避开坐标标签）
          const ly = bestOne.name === 'A' || bestOne.name === 'B' ? Math.max(22, py - 34) : bestOne.name === 'C' ? py + 34 : py + 18;
          tag(
            ctx,
            st.best.length > 1 ? L({ zh: '整条边都最优', en: 'whole edge optimal' }) : L({ zh: '最优解', en: 'optimal point' }),
            px + 16,
            ly,
            pal.point,
            'left',
            10,
          );
        }
      },
    });

    defineLesson('linearProgramming', {
      lesson: {
        zh: '线性规划的标准解法是“图解法”：把每个不等式画成半平面，交集就是可行域（这里是四边形 OABC）。目标函数 z = c₁x + c₂y 的等值线是一族平行直线，z 越大，直线越往 z 增大的方向平移。让等值线从一头滑到另一头，最后碰到可行域的位置就是最优解——由于可行域是凸多边形，这个位置一定是某个顶点。',
        en: 'Solve linear programs graphically: each inequality is a half-plane and their intersection is the feasible region (here the quadrilateral OABC). The level lines of z = c₁x + c₂y are a family of parallel lines; sliding them in the direction where z grows, the last line that still touches the region gives the optimum. Because the region is a convex polygon, that touch point is always a vertex.',
      },
      steps: [
        { at: 0, zh: '可行域由 x ≥ 0、y ≥ 0、x + y ≤ 6、2x + y ≤ 8 围成，四个顶点是 O(0,0)、A(0,6)、B(2,4)、C(4,0)。', en: 'The region is bounded by x ≥ 0, y ≥ 0, x + y ≤ 6 and 2x + y ≤ 8; its vertices are O(0,0), A(0,6), B(2,4), C(4,0).' },
        { at: 0.3, zh: '等值线 z = c₁x + c₂y 是一族平行线，斜率由 c₁、c₂ 决定；和可行域的边比较斜率，就能看出它从哪条边“离开”。', en: 'The level lines z = c₁x + c₂y are parallel; their slope comes from c₁ and c₂. Comparing with the edges shows which edge the sliding line leaves through.' },
        { at: 0.6, zh: '等值线平移时 z 在变。它扫过可行域的内部，但只有在顶点处才停得住——内部点总还能再往“更优”的方向挪一点。', en: 'As the line slides, z changes. It sweeps the interior but can only stop at a vertex: an interior point can always be shifted a little further in the improving direction.' },
        { at: 0.88, zh: '最后等值线与可行域只剩一个公共点（最优顶点），此时 z 取到最值；把四个顶点的 z 都算出来比较，答案一定在其中。', en: 'At the end the line shares a single point with the region — the optimal vertex — where z is extremal. Compute z at all four vertices and compare; the answer is always one of them.' },
      ],
    });

    defineQuiz('linearProgramming', (rng) => {
      const c1 = rnum(rng, -3, 3, 1);
      let c2 = rnum(rng, -3, 3, 1);
      if (c1 === 0 && c2 === 0) c2 = 2;
      const goal = rpick(rng, ['max', 'min']);
      const isMax = goal === 'max';
      const verts = linearVertices().map((v) => Object.assign({}, v, { z: linearObjective(c1, c2, v.x, v.y) }));
      const zs = verts.map((v) => v.z);
      const zMax = Math.max.apply(null, zs);
      const zMin = Math.min.apply(null, zs);
      const bestZ = isMax ? zMax : zMin;
      const best = verts.filter((v) => Math.abs(v.z - bestZ) < 1e-9);
      const params = { c1, c2, goal };
      const expr = linearExpr(c1, c2).replace('z = ', '');
      const label = isMax ? '最大' : '最小';
      const labelEn = isMax ? 'maximum' : 'minimum';
      const values = verts.map((v) => `${v.name}=${fnum(v.z, 2)}`).join('，');

      return makeQuiz(
        params,
        {
          zh: `已知 x、y 满足 x ≥ 0，y ≥ 0，x + y ≤ 6，2x + y ≤ 8，求 z = ${expr} 的${label}值。`,
          en: `Given x ≥ 0, y ≥ 0, x + y ≤ 6, 2x + y ≤ 8, find the ${labelEn} of z = ${expr}.`,
        },
        '',
        bestZ,
        {
          zh: `四个顶点的 z 值：${values}。其中${label}值为 ${fnum(bestZ, 2)}，在顶点 ${best.map((v) => `${v.name}(${v.x}, ${v.y})`).join('、')} 处取得。`,
          en: `Vertex values: ${values}. The ${labelEn} is ${fnum(bestZ, 2)} at ${best.map((v) => `${v.name}(${v.x}, ${v.y})`).join(', ')}.`,
        },
        0.005,
      );
    });

