    // ---- src/models/parabola.js -------------------------------------
    // ---------------------------------------------------------------------------
    // 模型 C4 · 抛物线（高二：焦点、准线、|PF| = 到准线的距离）
    // ---------------------------------------------------------------------------

    /** 四个开口方向对应的单位向量：u 沿对称轴指出去，v 与之垂直 */
    function pbAxes(dir) {
      if (dir === 'left') return { u: [-1, 0], v: [0, -1] };
      if (dir === 'up') return { u: [0, 1], v: [-1, 0] };
      if (dir === 'down') return { u: [0, -1], v: [1, 0] };
      return { u: [1, 0], v: [0, 1] };
    }

    /** 系数 2p 的文字形式：等于 1 时省略，写「y² = x」而不是「y² = 1x」 */
    function pbCoefText(v) {
      return Math.abs(v - 1) < 1e-9 ? '' : fnum(v, 2);
    }

    /** 抛物线的派生量：p 是焦准距，方程形如 y² = 2px（开口向右） */
    function pbGeom(p) {
      const pp = clamp(Number(p.p) || 2, 0.5, 6);
      const dir = ['right', 'left', 'up', 'down'].includes(p.dir) ? p.dir : 'right';
      // 画面：横向（沿轴）留出准线一侧，纵向取 2 倍半高
      const yHalf = clamp(0.8 * pp + 1.4, 1.5, 5.2);
      const xBack = pp / 2 + 1.3;
      const xExit = Math.min((yHalf * yHalf) / (2 * pp), 8.5);
      const xFwd = Math.max(pp / 2 + 1.2, xExit + 0.8);
      // 动点参数 s（沿 v 方向的坐标）控制在画面内
      const S = Math.min(0.82 * yHalf, Math.sqrt(Math.max(0.01, 2 * pp * 0.84 * xFwd)));
      return { p: pp, dir, yHalf, xBack, xFwd, S, xExit };
    }

    defineModel({
      id: 'parabola',
      grade: 2,
      name: { zh: '抛物线', en: 'Parabola' },
      formula: {
        zh: 'y² = 2px　焦点 (p/2, 0)　准线 x = −p/2　|PF| = x + p/2　通径 2p',
        en: 'y² = 2px　focus (p/2, 0)　directrix x = −p/2　|PF| = x + p/2　latus rectum 2p',
      },
      hint: {
        zh: '抛物线上任意一点到焦点的距离，等于它到准线的距离——这就是定义，也是「|PF| = x + p/2」的来历。参数 p 是焦点到准线的距离，焦点在 (p/2, 0)，准线是 x = −p/2，过焦点垂直于对称轴的弦（通径）长 2p。',
        en: 'On a parabola the distance to the focus equals the distance to the directrix — that is the definition, and it is why |PF| = x + p/2. The parameter p is the focus-to-directrix distance: focus (p/2, 0), directrix x = −p/2, and the latus rectum (focal chord perpendicular to the axis) has length 2p.',
      },
      chartLabel: { zh: '|PF|', en: '|PF|' },
      timeline: {
        zh: '动画：P 沿抛物线从一支到另一支，|PF| 始终等于到准线的距离',
        en: 'Animation: P runs along the parabola while |PF| stays equal to the distance to the directrix',
      },
      params: [
        { key: 'p', label: { zh: '焦准距 p', en: 'Focus–directrix p' }, min: 0.5, max: 6, step: 0.1, init: 2, unit: '', digits: 1 },
        {
          key: 'dir',
          label: { zh: '开口方向', en: 'Opening' },
          kind: 'select',
          init: 'right',
          options: [
            { value: 'right', label: { zh: '向右', en: 'right' } },
            { value: 'left', label: { zh: '向左', en: 'left' } },
            { value: 'up', label: { zh: '向上', en: 'up' } },
            { value: 'down', label: { zh: '向下', en: 'down' } },
          ],
        },
      ],

      box(p) {
        const g = pbGeom(p);
        // 统一在「开口向右」的坐标系里算，再按方向翻转
        if (g.dir === 'right') {
          return { xMin: -g.xBack, xMax: g.xFwd, yMin: -g.yHalf, yMax: g.yHalf };
        }
        if (g.dir === 'left') {
          return { xMin: -g.xFwd, xMax: g.xBack, yMin: -g.yHalf, yMax: g.yHalf };
        }
        if (g.dir === 'up') {
          return { xMin: -g.yHalf, xMax: g.yHalf, yMin: -g.xBack, yMax: g.xFwd };
        }
        return { xMin: -g.yHalf, xMax: g.yHalf, yMin: -g.xFwd, yMax: g.xBack };
      },

      duration() {
        return 7;
      },

      state(t, p) {
        const g = pbGeom(p);
        const total = this.duration(p);
        const u01 = clamp(t / total, 0, 1);
        const s = -g.S + 2 * g.S * u01;
        const [ux, uy] = pbAxes(g.dir).u;
        const [vx, vy] = pbAxes(g.dir).v;
        const along = (s * s) / (2 * g.p);
        const px = ux * along + vx * s;
        const py = uy * along + vy * s;
        const fx = ux * (g.p / 2);
        const fy = uy * (g.p / 2);
        // 到准线与到焦点的距离是同一个数：沿轴的坐标 + p/2
        const dist = along + g.p / 2;
        const qx = px - ux * dist;
        const qy = py - uy * dist;

        // 准线的位置：沿对称轴 −u 方向 p/2 处，向左/向下开口时翻到正半轴
        const dirX = -ux * (g.p / 2);
        const dirY = -uy * (g.p / 2);
        const sign = g.dir === 'left' || g.dir === 'down' ? '−' : '';
        const coef = pbCoefText(2 * g.p);
        const eq = g.dir === 'up' || g.dir === 'down' ? `x² = ${sign}${coef}y` : `y² = ${sign}${coef}x`;
        const dirText = {
          right: { zh: '向右', en: 'right' },
          left: { zh: '向左', en: 'left' },
          up: { zh: '向上', en: 'up' },
          down: { zh: '向下', en: 'down' },
        }[g.dir];

        return {
          t,
          p: g.p,
          dir: g.dir,
          s,
          px,
          py,
          fx,
          fy,
          qx,
          qy,
          dirX,
          dirY,
          dist,
          S: g.S,
          eq,
          dirText,
          summary: {
            zh: `${L(dirText)}开口的抛物线 ${eq}：焦点到准线的距离 p = ${fnum(g.p, 2)}，|PF| = ${fnum(dist, 2)} 恰好等于 P 到准线的距离。`,
            en: `For ${eq} opening ${L(dirText).toLowerCase()}: p = ${fnum(g.p, 2)}, and |PF| = ${fnum(dist, 2)} equals the distance from P to the directrix.`,
          },
          chartValue: dist,
          rows: [
            { label: { zh: '方程', en: 'Equation' }, value: eq },
            { label: { zh: '焦点 F', en: 'Focus F' }, value: `(${fnum(fx, 2)}, ${fnum(fy, 2)})` },
            {
              label: { zh: '准线', en: 'Directrix' },
              value:
                g.dir === 'up' || g.dir === 'down'
                  ? `y = ${fnum(dirY, 2)}`
                  : `x = ${fnum(dirX, 2)}`,
            },
            { label: { zh: '|PF|', en: '|PF|' }, value: fnum(dist, 2) },
            { label: { zh: 'P 到准线的距离', en: 'Distance to directrix' }, value: fnum(dist, 2) },
            { label: { zh: '通径 2p', en: 'Latus rectum 2p' }, value: fnum(2 * g.p, 2) },
          ],
        };
      },

      draw(ctx, st, view, pal, opts, p) {
        const g = pbGeom(p);
        const [ux, uy] = pbAxes(g.dir).u;
        const [vx, vy] = pbAxes(g.dir).v;
        const P = { x: st.px, y: st.py };
        const F = { x: st.fx, y: st.fy };
        const Q = { x: st.qx, y: st.qy };

        // 抛物线：参数方程 (s²/2p)·u + s·v 描点，一直画到出画面
        const reach = Math.max(
          Math.abs(view.x1 - view.x0),
          Math.abs(view.y1 - view.y0),
        );
        const sDraw = Math.min(4 * reach, Math.max(g.S * 1.35, Math.sqrt(Math.max(0.01, 2 * g.p * reach))));
        const pts = [];
        const steps = 260;
        for (let i = 0; i <= steps; i += 1) {
          const ss = -sDraw + (2 * sDraw * i) / steps;
          const along = (ss * ss) / (2 * g.p);
          pts.push([ux * along + vx * ss, uy * along + vy * ss]);
        }
        polylineWorld(ctx, view, pts, pal.curve, 2.4);

        // 准线（垂直于对称轴的整条直线）
        const dl = Math.max(reach, 12);
        segmentWorld(
          ctx,
          view,
          -ux * (g.p / 2) - vx * dl,
          -uy * (g.p / 2) - vy * dl,
          -ux * (g.p / 2) + vx * dl,
          -uy * (g.p / 2) + vy * dl,
          pal.tangent,
          1.8,
          [7, 5],
        );
        labelWorld(
          ctx,
          view,
          g.dir === 'up' || g.dir === 'down' ? `y = ${fnum(st.dirY, 2)}` : `x = ${fnum(st.dirX, 2)}`,
          st.dirX + vx * (g.yHalf * 0.86),
          st.dirY + vy * (g.yHalf * 0.86),
          pal.tangent,
          g.dir === 'right' ? 'left' : g.dir === 'left' ? 'right' : 'center',
          10,
        );

        // 通径：过焦点垂直于对称轴的弦，长 2p
        const vLimit = Math.abs(vx) > 0.5 ? Math.abs(view.x1) : Math.abs(view.y1);
        const lat = Math.min(g.p, vLimit * 0.78);
        segmentWorld(ctx, view, F.x - vx * lat, F.y - vy * lat, F.x + vx * lat, F.y + vy * lat, pal.curve3, 1.5, [5, 4]);
        const labT = Math.min(lat + 0.32, vLimit * 0.9);
        labelWorld(
          ctx,
          view,
          `2p = ${fnum(2 * g.p, 2)}`,
          F.x + vx * labT + ux * 0.18,
          F.y + vy * labT + uy * 0.18,
          pal.curve3,
          'center',
          9,
        );

        // P 到准线的垂线（垂足 Q）与到焦点的连线
        segmentWorld(ctx, view, P.x, P.y, Q.x, Q.y, pal.curve2, 1.8, [6, 4]);
        segmentWorld(ctx, view, P.x, P.y, F.x, F.y, pal.curve3, 2);
        rightAngle(ctx, view, Q.x, Q.y, ux, uy, vx, vy, pal.muted, 8);

        // 两条相等的线段只标记号（数值统一放在角落，避免和坐标刻度打架）
        // |PF| 固定在 +v 一侧，|PQ| 固定在 −v 一侧，两条标签永远分得开
        const offN = 0.55;
        const tagOnSegment = (A, B, text, color, side) => {
          const dx = B.x - A.x;
          const dy = B.y - A.y;
          const len = Math.hypot(dx, dy) || 1;
          let nx = -dy / len;
          let ny = dx / len;
          if ((nx * vx + ny * vy) * side < 0) {
            nx = -nx;
            ny = -ny;
          }
          const mid = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };
          labelWorld(ctx, view, text, mid.x + nx * offN, mid.y + ny * offN, color, 'center', 10);
        };
        tagOnSegment(P, F, '|PF|', pal.curve3, 1);
        tagOnSegment(P, Q, '|PQ|', pal.curve2, -1);

        // 焦点、动点、垂足
        dotWorld(ctx, view, F.x, F.y, pal.point, 4.4);
        labelWorld(ctx, view, 'F', F.x - vx * 0.32, F.y - vy * 0.32, pal.point, 'center', 11);
        dotWorld(ctx, view, Q.x, Q.y, pal.point, 3.6);
        labelWorld(ctx, view, 'Q', Q.x - ux * 0.3, Q.y - uy * 0.3, pal.point, 'center', 10);
        dotWorld(ctx, view, P.x, P.y, pal.tangent, 4.8);
        const sgn = st.s >= 0 ? 1 : -1;
        // 顶点附近往开口外侧挪一点，别压在对称轴上
        const shiftU = Math.abs(st.s) < 0.4 ? -0.38 : 0;
        labelWorld(
          ctx,
          view,
          'P',
          P.x + vx * 0.44 * sgn + ux * shiftU,
          P.y + vy * 0.44 * sgn + uy * shiftU,
          pal.tangent,
          'center',
          11,
        );

        // 角落：方程 + 两个相等的距离（放在准线一侧的空白处）
        const corner = {
          right: { x: view.x0 + (view.x1 - view.x0) * 0.03, y: view.y1 - 0.45, align: 'left', step: -0.62 },
          left: { x: view.x1 - (view.x1 - view.x0) * 0.03, y: view.y1 - 0.45, align: 'right', step: -0.62 },
          up: { x: view.x0 + (view.x1 - view.x0) * 0.03, y: view.y0 + 1.15, align: 'left', step: -0.62 },
          down: { x: view.x0 + (view.x1 - view.x0) * 0.03, y: view.y1 - 0.45, align: 'left', step: -0.62 },
        }[g.dir];
        labelWorld(ctx, view, st.eq, corner.x, corner.y, pal.text, corner.align, 11);
        labelWorld(
          ctx,
          view,
          L({ zh: `|PF| = |PQ| = ${fnum(st.dist, 2)}`, en: `|PF| = |PQ| = ${fnum(st.dist, 2)}` }),
          corner.x,
          corner.y + corner.step,
          pal.curve3,
          corner.align,
          10,
        );
      },
    });

    defineLesson('parabola', {
      lesson: {
        zh: '抛物线是「到定点 F 和到定直线 l 距离相等」的点的轨迹：定点是焦点，定直线是准线。以开口向右为例，焦点 F(p/2, 0)、准线 x = −p/2，标准方程 y² = 2px。于是焦半径 |PF| = x + p/2，与到准线的距离完全一样；过焦点垂直于对称轴的弦（通径）长为 2p，是过焦点的最短弦。',
        en: 'A parabola is the locus of points equidistant from a fixed point F (the focus) and a fixed line (the directrix). Opening right: F(p/2, 0), directrix x = −p/2, standard form y² = 2px. Hence |PF| = x + p/2, exactly the distance to the directrix; the focal chord perpendicular to the axis (latus rectum) has length 2p and is the shortest chord through the focus.',
      },
      steps: [
        { at: 0, zh: 'P 在抛物线的一支上：先量 |PF|，再量它到准线的垂线长度，两者相等——这就是抛物线的定义。', en: 'P sits on one arm: measure |PF| and the perpendicular distance to the directrix — they are equal, which is the definition.' },
        { at: 0.3, zh: 'P 靠近顶点时两个距离都变短，仍然相等；顶点到焦点和到准线的距离都是 p/2。', en: 'Near the vertex both distances shrink together and stay equal; the vertex is p/2 from the focus and from the directrix.' },
        { at: 0.5, zh: 'P 到达顶点：这是曲线上离准线（和焦点）最近的点，距离为 p/2。', en: 'At the vertex P is closest to the directrix (and to the focus): the distance is p/2.' },
        { at: 0.75, zh: 'P 走向另一支：|PF| 越来越大，p 只决定开口的宽窄——p 越大开口越开阔，通径 2p 也越长。', en: 'P heads up the other arm: |PF| grows. Only p sets the width — larger p opens wider and lengthens the latus rectum 2p.' },
      ],
    });

    defineQuiz('parabola', (rng) => {
      const p = rnum(rng, 1, 6, 0.5);
      const dir = rpick(rng, ['right', 'left', 'up', 'down']);
      const along = p / 2;
      const kind = Math.floor(rng() * 3);
      const dirName = {
        right: { zh: '向右', en: 'right' },
        left: { zh: '向左', en: 'left' },
        up: { zh: '向上', en: 'up' },
        down: { zh: '向下', en: 'down' },
      }[dir];
      const qcoef = pbCoefText(2 * p);
      const qsign = dir === 'left' || dir === 'down' ? '−' : '';
      const eq = dir === 'up' || dir === 'down' ? `x² = ${qsign}${qcoef}y` : `y² = ${qsign}${qcoef}x`;

      if (kind === 0) {
        return makeQuiz(
          { p, dir },
          {
            zh: `抛物线 ${eq} 的通径（过焦点垂直于对称轴的弦）长是多少？`,
            en: `What is the length of the latus rectum of the parabola ${eq}?`,
          },
          '',
          2 * p,
          {
            zh: `对 y² = 2px，通径长 = 2p = 2 × ${fnum(p, 1)} = ${fnum(2 * p, 2)}（通径的两个端点横坐标都是 p/2，纵坐标是 ±p）。`,
            en: `For y² = 2px the latus rectum is 2p = ${fnum(2 * p, 2)}: its endpoints are (p/2, ±p).`,
          },
          0.01,
        );
      }
      if (kind === 1) {
        // 开口向左/向下时焦点在负半轴，准线翻到正半轴
        const ans = dir === 'left' || dir === 'down' ? p / 2 : -p / 2;
        const lineText = dir === 'up' || dir === 'down' ? `y = ${fnum(ans, 2)}` : `x = ${fnum(ans, 2)}`;
        const lineAxis = dir === 'up' || dir === 'down' ? 'y' : 'x';
        return makeQuiz(
          { p, dir },
          {
            zh: `抛物线 ${eq} 的焦点到准线的距离为 ${fnum(p, 1)}，求它的准线方程。答案填写准线对应的坐标值（例如 x = −1 就填 −1）。`,
            en: `The parabola ${eq} has focus–directrix distance ${fnum(p, 1)}. Give the directrix as a number (for x = −1 enter −1).`,
          },
          '',
          ans,
          {
            zh: `开口${dirName.zh}时，焦点在开口一侧、距顶点 p/2 = ${fnum(p / 2, 2)}；准线在顶点的另一侧、与焦点关于顶点对称，所以准线是 ${lineText}。`,
            en: `Opening ${dirName.en} puts the focus p/2 = ${fnum(p / 2, 2)} from the vertex along the axis; the directrix is symmetric about the vertex, so it is ${lineAxis} = ${fnum(ans, 2)}.`,
          },
          0.01,
        );
      }
      const s = rnum(rng, 1, 3, 0.5);
      const px = (s * s) / (2 * p);
      const py = s;
      const dist = px + p / 2;
      // 3 位小数：这些点正好落在抛物线上，写 2 位会让学生验算时对不上
      const xText = dir === 'right' ? fnum(px, 3) : dir === 'left' ? fnum(-px, 3) : fnum(dir === 'up' ? -s : s, 3);
      const yText =
        dir === 'right' ? fnum(py, 3) : dir === 'left' ? fnum(-py, 3) : dir === 'up' ? fnum(px, 3) : fnum(-px, 3);
      return makeQuiz(
        { p, dir },
        {
          zh: `抛物线 ${eq} 上一点 P 的坐标为 (${xText}, ${yText})，求 |PF|。`,
          en: `A point P(${xText}, ${yText}) lies on ${eq}. Find |PF|.`,
        },
        '',
        dist,
        {
          zh: `用抛物线定义：|PF| = P 到准线的距离 = 沿对称轴方向的坐标 + p/2 = ${fnum(px, 3)} + ${fnum(
            p / 2,
            2,
          )} = ${fnum(dist, 3)}。`,
          en: `By definition |PF| equals the distance to the directrix: ${fnum(px, 3)} + p/2 = ${fnum(dist, 3)}.`,
        },
        0.02,
      );
    });

    defineExams([
      {
        id: 'ex-parabola-1',
        modelId: 'parabola',
        source: { zh: '高考题型 · 改编', en: 'Exam-style · adapted' },
        tag: { zh: '通径', en: 'Latus rectum' },
        params: { p: 4, dir: 'right' },
        stem: {
          zh: '已知抛物线 y² = 8x，求它的焦点坐标与通径长。答案填写通径长。',
          en: 'For the parabola y² = 8x, find the focus and the length of the latus rectum. Enter the latus rectum length.',
        },
        unit: '',
        answer: 8,
        tol: 0.01,
        solution: {
          zh: '2p = 8 得 p = 4，焦点为 (p/2, 0) = (2, 0)，准线 x = −2；通径长 = 2p = 8。',
          en: '2p = 8 gives p = 4, so the focus is (2,0), the directrix is x = −2 and the latus rectum is 2p = 8.',
        },
      },
      {
        id: 'ex-parabola-2',
        modelId: 'parabola',
        source: { zh: '高考题型 · 改编', en: 'Exam-style · adapted' },
        tag: { zh: '焦半径', en: 'Focal radius' },
        params: { p: 6, dir: 'right' },
        stem: {
          zh: '抛物线 y² = 12x 上一点 P 到焦点的距离为 5，求 P 的横坐标。',
          en: 'A point P on y² = 12x is 5 units from the focus. Find the x-coordinate of P.',
        },
        unit: '',
        answer: 2,
        tol: 0.01,
        solution: {
          zh: '2p = 12 得 p = 6，焦点 (3, 0)，准线 x = −3。由定义 |PF| = x + 3 = 5，所以 x = 2（此时 y² = 24，y = ±2√6）。',
          en: '2p = 12 gives p = 6: focus (3,0), directrix x = −3. By definition |PF| = x + 3 = 5, so x = 2 (then y = ±2√6).',
        },
      },
    ]);

    // ---- src/models/probability.js ----------------------------------
    // ---------------------------------------------------------------------------
    // 模型 · 二项分布 B(n, p)（高三）
    // ---------------------------------------------------------------------------

    /**
     * 二项分布整行概率 P(X = k)，k = 0…n。
     * 递推：P(k+1) / P(k) = (n−k)/(k+1) · p/(1−p)，省掉组合数与阶乘。
     */
    function probBinomialRow(n, p) {
      const row = [];
      if (!(p > 0)) {
        for (let k = 0; k <= n; k += 1) row.push(k === 0 ? 1 : 0);
        return row;
      }
      if (!(p < 1)) {
        for (let k = 0; k <= n; k += 1) row.push(k === n ? 1 : 0);
        return row;
      }
      const q = 1 - p;
      let value = Math.pow(q, n);
      row.push(value);
      for (let k = 0; k < n; k += 1) {
        value = (value * (n - k) * p) / ((k + 1) * q);
        row.push(value);
      }
      return row;
    }

    /** 二项分布的最可能值：floor((n+1)p)；当 (n+1)p 是整数时有两个并列的峰 */
    function probModes(n, p) {
      const m = (n + 1) * p;
      const out = [Math.min(Math.max(Math.floor(m + 1e-12), 0), n)];
      if (Math.abs(m - Math.round(m)) < 1e-9) {
        const other = Math.round(m) - 1;
        if (other >= 0 && other <= n && other !== out[0]) out.push(other);
      }
      return out.sort((a, b) => a - b);
    }

    /** 概率读数：0.17623 → 0.1762 */
    function probNumText(v, digits) {
      const d = digits === undefined ? 4 : digits;
      return fx(Math.min(1, Math.max(0, v)), d);
    }

    /** 百分比读数：0.17623 → 17.62% */
    function probPctText(v, digits) {
      const d = digits === undefined ? 2 : digits;
      return `${fx(Math.min(1, Math.max(0, v)) * 100, d)}%`;
    }

    /** 纵轴刻度步长：0…yMax 大约分 4–5 格 */
    function probYStep(yMax) {
      const steps = [0.001, 0.002, 0.005, 0.01, 0.02, 0.025, 0.05, 0.1, 0.2, 0.25, 0.5];
      for (let i = 0; i < steps.length; i += 1) {
        if (yMax / steps[i] <= 5.5) return steps[i];
      }
      return steps[steps.length - 1];
    }

    /** 刻度数字：0 写 0，其余按步长取位 */
    function probTickText(v, step) {
      if (Math.abs(v) < 1e-12) return '0';
      return fx(v, step < 0.01 ? 3 : 2);
    }

    defineModel({
      id: 'probability',
      grade: 3,
      name: { zh: '二项分布 B(n, p)', en: 'Binomial distribution' },
      formula: {
        zh: 'P(X = k) = C(n,k) pᵏ(1 − p)ⁿ⁻ᵏ　·　E(X) = np　·　D(X) = np(1 − p)',
        en: 'P(X=k) = C(n,k) pᵏ(1−p)ⁿ⁻ᵏ · E(X) = np · D(X) = np(1−p)',
      },
      hint: {
        zh: 'n 次独立重复试验里“成功 k 次”的概率按 k 排开就是二项分布：峰在 np 附近，柱子先升后降，所有柱高之和恒为 1。所以 P(X ≤ k) 就是把左边这些柱子加起来——动画里那截橙色就是它。',
        en: 'Lay out the chance of exactly k successes in n independent trials: the bars peak near np and always sum to 1. So P(X ≤ k) is just the bars from 0 to k added up — the orange ones in the animation.',
      },
      chartLabel: { zh: 'P(X = k)', en: 'P(X = k)' },
      timeline: {
        zh: '动画：k 从 0 扫到目标 k，累计概率一格一格加上去',
        en: 'Animation: k sweeps 0 → target, adding the cumulative probability bar by bar',
      },
      // 21 根柱子挤在等比缩放的坐标系里只有几像素高，这里自己管横纵比例
      noAxes: true,
      params: [
        { key: 'n', label: { zh: '试验次数 n', en: 'Trials n' }, min: 5, max: 20, step: 1, init: 10, unit: '', digits: 0 },
        { key: 'p', label: { zh: '单次成功概率 p', en: 'Success probability p' }, min: 0.05, max: 0.95, step: 0.05, init: 0.5, unit: '', digits: 2 },
        { key: 'k', label: { zh: '目标次数 k', en: 'Target k' }, min: 0, max: 20, step: 1, init: 7, unit: '', digits: 0 },
      ],
      box(p) {
        const n = Math.max(1, Math.round(p.n));
        return { xMin: -0.5, xMax: n + 0.5, yMin: 0, yMax: 1 };
      },
      duration() {
        return 4.4;
      },
      state(t, p) {
        const n = Math.round(p.n);
        const pp = clamp(p.p, 0, 1);
        const row = probBinomialRow(n, pp);
        let maxP = 0;
        row.forEach((v) => {
          if (v > maxP) maxP = v;
        });
        const target = Math.min(Math.max(0, Math.round(p.k)), n);
        const total = this.duration(p);
        const tt = Math.min(Math.max(t, 0), total);
        const progress = total > 0 ? tt / total : 1;
        const r = Math.min(target, Math.round(target * progress));
        let cum = 0;
        for (let i = 0; i <= r; i += 1) cum += row[i];
        cum = Math.min(1, Math.max(0, cum));

        const mean = n * pp;
        const variance = n * pp * (1 - pp);
        const sigma = Math.sqrt(Math.max(0, variance));
        const modes = probModes(n, pp);
        const modeText = modes.length > 1 ? `${modes[0]} / ${modes[1]}` : String(modes[0]);

        const current = row[r];
        const skew = Math.abs(pp - 0.5) < 1e-9 ? 'sym' : pp < 0.5 ? 'right' : 'left';
        let summary;
        if (skew === 'sym') {
          summary = {
            zh: `p = 0.5：分布关于 k = n/2 = ${fnum(n / 2, 1)} 对称，最可能值是 k = ${modeText}；P(X ≤ k) 随 k 单调增加到 1。`,
            en: `p = 0.5: the distribution is symmetric about k = n/2 = ${fnum(n / 2, 1)}, with modes k = ${modeText}; P(X ≤ k) climbs monotonically to 1.`,
          };
        } else if (skew === 'right') {
          summary = {
            zh: `p < 0.5，分布右偏（右侧长尾）；峰在 k = ${modeText}，而均值 np = ${fnum(mean, 2)} 被长尾拉向右边。`,
            en: `p < 0.5 gives a right-skewed shape: the mode is k = ${modeText} but the mean np = ${fnum(mean, 2)} is pulled right by the tail.`,
          };
        } else {
          summary = {
            zh: `p > 0.5，分布左偏（左侧长尾）；峰在 k = ${modeText}，而均值 np = ${fnum(mean, 2)} 被长尾拉向左边。`,
            en: `p > 0.5 gives a left-skewed shape: the mode is k = ${modeText} but the mean np = ${fnum(mean, 2)} is pulled left by the tail.`,
          };
        }

        return {
          t: tt,
          n,
          p: pp,
          r,
          row,
          maxP,
          cum,
          mean,
          variance,
          sigma,
          modes,
          modeText,
          summary,
          chartValue: isFinite(current) ? current : 0,
          rows: [
            { label: { zh: '当前 k', en: 'Current k' }, value: `k = ${r}` },
            { label: { zh: 'P(X = k)', en: 'P(X = k)' }, value: probNumText(current, 4) },
            { label: { zh: '累计 P(X ≤ k)', en: 'Cumulative P(X ≤ k)' }, value: `${probNumText(cum, 3)} (${probPctText(cum, 1)})` },
            { label: { zh: '期望 E(X) = np', en: 'Mean E(X) = np' }, value: fnum(mean, 2) },
            { label: { zh: '方差 D(X) = np(1−p)', en: 'Variance D(X) = np(1−p)' }, value: fnum(variance, 2) },
            { label: { zh: '标准差 √D(X)', en: 'Std. deviation √D(X)' }, value: fnum(sigma, 2) },
            { label: { zh: '最可能值', en: 'Most likely k' }, value: modeText },
          ],
        };
      },
      draw(ctx, st, view, pal, opts, p) {
        const w = view.width;
        const h = view.height;
        const n = st.n;
        const row = st.row;
        const padL = w < 460 ? 42 : 52;
        const padR = 16;
        const top = 50;
        const bottom = h - 44;
        const plotW = Math.max(60, w - padL - padR);
        const plotH = Math.max(40, bottom - top);
        const maxP = Math.max(st.maxP, 1e-9);
        const yMax = maxP * 1.18;
        const sx = plotW / (n + 1);
        const sy = plotH / yMax;
        const toX = (x) => padL + (x + 0.5) * sx;
        const toY = (y) => bottom - y * sy;
        const gview = {
          width: w,
          height: h,
          toX,
          toY,
          x0: -0.5,
          x1: n + 0.5,
          y0: 0,
          y1: yMax,
          px: (len) => len * sx,
          scale: sx,
          unitsPerPx: 1 / Math.max(sx, 1e-6),
        };

        // ---- 顶部：分布记号 + 累计概率进度条 ----
        ctx.save();
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'left';
        ctx.font = `600 12px ${FONT_UI}`;
        ctx.fillStyle = pal.text;
        ctx.fillText(`X ~ B(${n}, ${fnum(st.p, 2)})`, padL, 14);
        ctx.textAlign = 'right';
        ctx.font = `500 10px ${FONT_UI}`;
        ctx.fillStyle = pal.muted;
        ctx.fillText(`E(X) = np = ${fnum(st.mean, 2)}`, w - padR, 14);
        ctx.restore();

        const meterY = 30;
        const meterW = Math.min(plotW * 0.4, 320);
        const mview = {
          toX: (u) => padL + u * meterW,
          toY: (v) => meterY + 4 - v * 8,
        };
        regionWorld(ctx, mview, [[0, 0], [1, 0], [1, 1], [0, 1]], pal.track);
        if (st.cum > 1e-6) {
          regionWorld(ctx, mview, [[0, 0], [st.cum, 0], [st.cum, 1], [0, 1]], pal.point);
        }
        tag(
          ctx,
          `P(X ≤ ${st.r}) = ${probNumText(st.cum, 3)} · ${probPctText(st.cum, 1)}`,
          padL + meterW + 9,
          meterY,
          pal.point,
          'left',
          10,
        );

        // ---- 纵轴：网格 + 刻度 ----
        const yStep = probYStep(yMax);
        ctx.save();
        ctx.font = `500 10px ${FONT_UI}`;
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        for (let v = 0; v <= yMax + 1e-9; v += yStep) {
          const py = toY(v);
          if (v > 1e-9) {
            ctx.strokeStyle = pal.grid;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(padL, py);
            ctx.lineTo(padL + plotW, py);
            ctx.stroke();
          }
          ctx.fillStyle = pal.muted;
          ctx.fillText(probTickText(v, yStep), padL - 7, py);
        }
        ctx.restore();
        ctx.save();
        ctx.strokeStyle = pal.axis;
        ctx.lineWidth = 1.3;
        ctx.beginPath();
        ctx.moveTo(padL, top - 4);
        ctx.lineTo(padL, bottom);
        ctx.lineTo(padL + plotW, bottom);
        ctx.stroke();
        ctx.restore();
        tag(ctx, 'P(X = k)', padL + 4, top - 6, pal.muted, 'left', 9);

        // ---- 期望线 ----
        segmentWorld(ctx, gview, st.mean, 0, st.mean, yMax, pal.muted, 1, [4, 4]);
        tag(
          ctx,
          `np = ${fnum(st.mean, 2)}`,
          clamp(toX(st.mean), padL + 34, w - padR - 34),
          top + 9,
          pal.muted,
          'center',
          10,
        );

        // ---- 柱子：未累计的蓝色，累计到的橙色 ----
        const allBars = [];
        for (let k = 0; k <= n; k += 1) allBars.push({ x: k, w: 0.68, y: row[k], color: pal.curve });
        drawBars(ctx, gview, pal, allBars, { base: 0, alpha: 0.3 });
        const doneBars = [];
        for (let k = 0; k <= Math.min(st.r, n); k += 1) doneBars.push({ x: k, w: 0.68, y: row[k], color: pal.point });
        drawBars(ctx, gview, pal, doneBars, { base: 0, alpha: 0.92 });

        // 当前柱描边
        const barW = 0.68 * sx;
        const curTop = toY(row[st.r]);
        ctx.save();
        ctx.strokeStyle = pal.tangent;
        ctx.lineWidth = 1.5;
        ctx.strokeRect(toX(st.r) - barW / 2, curTop, barW, Math.max(1, bottom - curTop));
        ctx.restore();

        // ---- 柱顶概率（只在放得下时逐根标，保证不重叠）----
        ctx.save();
        ctx.font = `500 9px ${FONT_UI}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'bottom';
        ctx.fillStyle = pal.muted;
        if (sx >= 30) {
          for (let k = 0; k <= n; k += 1) {
            if (k === st.r) continue;
            if (row[k] < maxP * 0.02) continue;
            ctx.fillText(probNumText(row[k], 3), toX(k), toY(row[k]) - 5);
          }
        }
        ctx.restore();
        tag(
          ctx,
          probNumText(row[st.r], 4),
          toX(st.r),
          toY(row[st.r]) - 13,
          pal.tangent,
          'center',
          10,
        );

        // ---- 横轴刻度 ----
        const every = sx >= 18 ? 1 : sx >= 10 ? 2 : Math.ceil(n / 8);
        ctx.save();
        ctx.font = `500 9.5px ${FONT_UI}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillStyle = pal.muted;
        let kk = 0;
        for (; kk <= n; kk += 1) {
          const px = toX(kk);
          if (kk % every !== 0 && kk !== n) continue;
          ctx.strokeStyle = pal.axis;
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(px, bottom);
          ctx.lineTo(px, bottom + 4);
          ctx.stroke();
          ctx.fillText(String(kk), px, bottom + 7);
        }
        ctx.textAlign = 'right';
        ctx.font = `600 11px ${FONT_UI}`;
        ctx.fillText('k', padL + plotW, bottom + 21);
        ctx.restore();

        // ---- 右上角：最可能值提示 ----
        if (w >= 520) {
          tag(
            ctx,
            `${L({ zh: '最可能值', en: 'mode' })} k = ${st.modeText}`,
            w - padR,
            30,
            pal.curve3,
            'right',
            10,
          );
        }
      },
    });

    defineLesson('probability', {
      lesson: {
        zh: '二项分布是“n 次独立重复试验中成功次数”的分布律。它只由两个数决定：试验次数 n 和每次成功的概率 p。P(X = k) = C(n,k)pᵏ(1−p)ⁿ⁻ᵏ 里，C(n,k) 数的是“哪 k 次成功”，pᵏ(1−p)ⁿ⁻ᵏ 是每一种具体情形的概率。峰出现在 np 附近，柱子越高表示那个 k 越容易出现。',
        en: 'The binomial distribution is the law of the number of successes in n independent trials; it depends only on n and p. In P(X=k)=C(n,k)pᵏ(1−p)ⁿ⁻ᵏ, C(n,k) counts which k trials succeed and pᵏ(1−p)ⁿ⁻ᵏ is the probability of each pattern. The peak sits near np: taller bars mean likelier counts.',
      },
      steps: [
        { at: 0, zh: 'k = 0 时只有“一次都不成功”这一种情形，概率是 (1−p)ⁿ。此时累计概率就等于它自己。', en: 'At k = 0 only the all-failures case remains, with probability (1−p)ⁿ — and that is the cumulative probability too.' },
        { at: 0.3, zh: 'k 往右走，组合数 C(n,k) 变大，柱子迅速升高；累计概率把这些柱高一段段加起来。', en: 'As k grows, C(n,k) grows and the bars shoot up; the cumulative probability adds those heights up.' },
        { at: 0.6, zh: '峰落在 np 附近（精确说是 floor((n+1)p)）。p = 0.5 时图形左右对称，p 偏离 0.5 就会偏斜。', en: 'The peak sits near np — exactly at floor((n+1)p). With p = 0.5 the picture is symmetric; otherwise it skews.' },
        { at: 0.85, zh: '全部柱子的高之和恒为 1，所以扫到 k = n 时累计概率到达 1；E(X) = np 是柱子的重心。', en: 'All bar heights sum to 1, so at k = n the cumulative probability reaches 1; E(X) = np is the balance point of the bars.' },
      ],
    });

