        source: { zh: '高考题型 · 改编', en: 'Exam-style · adapted' },
        tag: { zh: '两角和的正弦', en: 'Sine of a sum' },
        params: { alpha: 45, beta: 30 },
        stem: {
          zh: '利用两角和的正弦公式求 sin75° 的值（保留三位小数）。',
          en: 'Use the addition formula to evaluate sin75° (three decimals).',
        },
